    "The device could not read or save the payment reference. Existing references were retained. Refresh before trying again.": "ডিভাইচে পৰিশোধৰ উল্লেখ পঢ়িব বা সংৰক্ষণ কৰিব নোৱাৰিলে। আগৰ উল্লেখসমূহ ৰখা হৈছে। পুনৰ চেষ্টা কৰাৰ আগতে ৰিফ্ৰেশ্ব কৰক।",
    "Payment status could not be confirmed. Any saved payment reference is retained. Refresh to verify before paying again.": "পৰিশোধৰ স্থিতি নিশ্চিত কৰিব পৰা নগ’ল। সংৰক্ষিত উল্লেখ ৰখা হৈছে। পুনৰ পৰিশোধৰ আগতে ৰিফ্ৰেশ্ব কৰি পৰীক্ষা কৰক।",
    "The server did not authorize checkout. Refresh your subscription details.": "চাৰ্ভাৰে চেকআউটৰ অনুমতি দিয়া নাই। সদস্যতাৰ তথ্য ৰিফ্ৰেশ্ব কৰক।",
    "The server could not establish the final payment status. Your saved reference is retained. Refresh before paying again.": "চাৰ্ভাৰে পৰিশোধৰ চূড়ান্ত স্থিতি নিৰ্ধাৰণ কৰিব নোৱাৰিলে। সংৰক্ষিত উল্লেখ ৰখা হৈছে। পুনৰ চেষ্টা কৰাৰ আগতে ৰিফ্ৰেশ্ব কৰক।",
    "{{plan}} will activate after verified payment.": "{{plan}} পৰীক্ষিত পৰিশোধৰ পিছত সক্ৰিয় হ’ব।",
