    "Higher-tier subscription active. {{minutes}} minutes of paid time preserved.": "উচ্চ স্তৰৰ সদস্যতা সক্ৰিয়। কিনা সময়ৰ {{minutes}} মিনিট সংৰক্ষিত আছে।",
    "{{plan}} will activate after verified payment. Your remaining {{days}} days of {{previous}} will be preserved and resume after higher-tier subscriptions finish.": "{{plan}} পৰীক্ষিত পৰিশোধৰ পিছত সক্ৰিয় হ’ব। বাকী {{days}} দিন {{previous}}ৰ বাবে সংৰক্ষিত থাকিব আৰু উচ্চ স্তৰৰ সদস্যতাসমূহ শেষ হ’লে পুনৰ চলিব।",
    "Your payment is verified. The subscription is active or scheduled as shown in My Subscription.": "আপোনাৰ পৰিশোধ পৰীক্ষা কৰা হৈছে। আৰম্ভণিৰ সময় মোৰ সদস্যতাত চাওক।",
