    "The payment is not confirmed yet. Your subscription will update after Cashfree verification. Use Refresh in Subscription & Billing to check again.": "পেমেন্ট এখনও নিশ্চিত নয়। Cashfree যাচাইয়ের পরে সদস্যতা আপডেট হবে। সদস্যতা ও বিলিংয়ে রিফ্রেশ করে দেখুন।",
    "The server applied your selection. Archived customers retain all history and outstanding-payment collection.": "সার্ভার নির্বাচন প্রয়োগ করেছে। আর্কাইভ গ্রাহকের ইতিহাস ও বকেয়া আদায় অক্ষত থাকবে।",
    "The server checks your available wallet balance again when creating the order. Any remainder is paid through Cashfree.": "অর্ডার তৈরির সময় সার্ভার ওয়ালেটের ব্যালেন্স আবার পরীক্ষা করে। বাকি অর্থ Cashfree দিয়ে পরিশোধ হবে।",
    "The server confirmed this payment failed. You can try again.": "সার্ভার পেমেন্ট ব্যর্থ হওয়া নিশ্চিত করেছে। আবার চেষ্টা করতে পারেন।",
    "The server could not establish the status of this saved payment reference. It has been retained. Refresh in the original shop and environment before starting another payment.": "সার্ভার সংরক্ষিত পেমেন্ট রেফারেন্সের অবস্থা জানতে পারেনি। সেটি রাখা হয়েছে। নতুন পেমেন্টের আগে মূল দোকান ও পরিবেশে রিফ্রেশ করুন।",
    "The server verified your payment, but this device could not refresh or save subscription details. Local synchronization is incomplete. Refresh when connected; do not pay again for this purchase.": "সার্ভার পেমেন্ট যাচাই করেছে, কিন্তু ডিভাইস সদস্যতার তথ্য রিফ্রেশ বা সংরক্ষণ করতে পারেনি। স্থানীয় সিঙ্ক অসম্পূর্ণ। সংযোগ পেলে রিফ্রেশ করুন; এই কেনার জন্য আবার পেমেন্ট করবেন না।",
    "There are no pending, failed, or conflicted local operations.": "কোনো বাকি, ব্যর্থ বা বিরোধপূর্ণ স্থানীয় কাজ নেই।",
