    "Confirm purchase": "কেনাকাটা নিশ্চিত করুন",
    "The device could not read or save the payment reference. Existing references were retained. Refresh before trying again.": "ডিভাইস পেমেন্টের রেফারেন্স পড়তে বা সংরক্ষণ করতে পারেনি। আগের রেফারেন্স রাখা হয়েছে। আবার চেষ্টা করার আগে রিফ্রেশ করুন।",
    "Payment status could not be confirmed. Any saved payment reference is retained. Refresh to verify before paying again.": "পেমেন্টের অবস্থা নিশ্চিত করা যায়নি। সংরক্ষিত রেফারেন্স রাখা হয়েছে। আবার পেমেন্টের আগে রিফ্রেশ করে যাচাই করুন।",
    "The server did not authorize checkout. Refresh your subscription details.": "সার্ভার চেকআউট অনুমোদন করেনি। সদস্যতার বিবরণ রিফ্রেশ করুন।",
    "The server could not establish the final payment status. Your saved reference is retained. Refresh before paying again.": "সার্ভার পেমেন্টের চূড়ান্ত অবস্থা নির্ধারণ করতে পারেনি। সংরক্ষিত রেফারেন্স রাখা হয়েছে। আবার চেষ্টা করার আগে রিফ্রেশ করুন।",
    "{{plan}} will activate after verified payment.": "{{plan}} যাচাইকৃত পেমেন্টের পরে সক্রিয় হবে।",
    "Your new {{plan}} subscription will start after the preceding subscription commitments.": "আপনার নতুন {{plan}} সদস্যতা আগের সদস্যতার মেয়াদগুলির পরে শুরু হবে।",
