    "The server checks your available wallet balance again when creating the order. Any remainder is paid through Cashfree.": "ऑर्डर बनांदे बेल्लै सर्वर वॉलेट बकाया फ्ही जांचदा ऐ। बाकी रकम Cashfree राहें अदा होंदी ऐ।",
