    "The server could not establish the status of this saved payment reference. It has been retained. Refresh in the original shop and environment before starting another payment.": "सर्वर सहेजे भुगतान हवाले दी हालत नेईं जानी सकेया। हवाला रखेया ऐ। नमें भुगतान शा पैह्लें असली दुकान ते माहौल च रिफ्रेश करो।",
    "The server verified your payment, but this device could not refresh or save subscription details. Local synchronization is incomplete. Refresh when connected; do not pay again for this purchase.": "सर्वर ने भुगतान जांचेया, पर उपकरण सदस्यता ब्यौरा रिफ्रेश जां सहेज नेईं सकेया। मकामी सिंक अधूरा ऐ। जुड़ने पर रिफ्रेश करो; इस खरीद लेई फ्ही भुगतान नेईं करो।",
    "There are no pending, failed, or conflicted local operations.": "कोई बाकी, नाकाम जां विवाद आह्ला मकामी कम्म नेईं।",
