    "Payment status could not be confirmed. Any saved payment reference is retained. Refresh to verify before paying again.": "भुगतान दी स्थिति दी पुष्टि नेईं होई सकी। बचाया संदर्भ रखेआ ऐ। परतियै भुगतान थमां पैह्लें रिफ्रेश करियै जांचो।",
