    "The server could not establish the final payment status. Your saved reference is retained. Refresh before paying again.": "सर्वर भुगतान दी आखरी स्थिति तय नेईं करी सकेआ। बचाया संदर्भ रखेआ ऐ। परतियै कोशिश थमां पैह्लें रिफ्रेश करो।",
