    "{{plan}} will activate after verified payment. Your remaining {{days}} days of {{previous}} will be preserved and resume after higher-tier subscriptions finish.": "{{plan}} तसदीक कीते भुगतान दे बाद सक्रिय होग। बाकी {{days}} दिन {{previous}} लेई सुरक्षित रौह्ङन ते उच्च स्तर दियां सदस्यतां मुक्कने पर परतियै शुरू होङन।",
    "Your payment is verified. The subscription is active or scheduled as shown in My Subscription.": "तुंदा भुगतान तसदीक होई गेआ। सक्रिय होने दा समां मेरी सदस्यता च दिक्खो।",
