    "Select active / restore archived customers": "સક્રિય પસંદ કરો / આર્કાઇવ ગ્રાહકો પાછા લાવો",
    "Select active customers": "સક્રિય ગ્રાહકો પસંદ કરો",
    "Select active customers within your plan limit. Existing records and outstanding payment collection remain available.": "પ્લાનની મર્યાદામાં સક્રિય ગ્રાહકો પસંદ કરો. જૂના રેકોર્ડ અને બાકી વસૂલાત ચાલુ રહેશે.",
