    "Selection needs review": "પસંદગી તપાસવી જરૂરી",
    "Share referral link": "રેફરલ લિંક શેર કરો",
    "Subscription Wallet": "સબ્સ્ક્રિપ્શન વૉલેટ",
    "Subscription access changed. Refresh and review active customers before adding credit.": "સબ્સ્ક્રિપ્શન અધિકાર બદલાયા. ઉધારી પહેલાં રિફ્રેશ કરીને સક્રિય ગ્રાહકો તપાસો.",
    "Subscription unavailable": "સબ્સ્ક્રિપ્શન ઉપલબ્ધ નથી",
    "Subtotal": "પેટાસરવાળો",
    "Suggest recently active customers": "તાજેતરમાં સક્રિય ગ્રાહકો સૂચવો",
    "The Free plan is already available without checkout.": "મફત પ્લાન ચુકવણી વગર પહેલેથી ઉપલબ્ધ છે.",
    "The payment is not confirmed yet. Your subscription will update after Cashfree verification. Use Refresh in Subscription & Billing to check again.": "ચુકવણીની હજી ખાતરી નથી. Cashfree ચકાસણી પછી સબ્સ્ક્રિપ્શન અપડેટ થશે. સબ્સ્ક્રિપ્શન અને બિલિંગમાં રિફ્રેશ કરો.",
    "The server applied your selection. Archived customers retain all history and outstanding-payment collection.": "સર્વરે પસંદગી લાગુ કરી. આર્કાઇવ ગ્રાહકોનો ઇતિહાસ અને બાકી વસૂલાત જળવાશે.",
    "The server checks your available wallet balance again when creating the order. Any remainder is paid through Cashfree.": "ઓર્ડર બનાવતી વખતે સર્વર વૉલેટ બેલેન્સ ફરી તપાસે છે. બાકીની રકમ Cashfree થી ચૂકવાય છે.",
    "The server confirmed this payment failed. You can try again.": "સર્વરે ચુકવણી નિષ્ફળ થયાની ખાતરી કરી. ફરી પ્રયાસ કરી શકો છો.",
    "The server could not establish the status of this saved payment reference. It has been retained. Refresh in the original shop and environment before starting another payment.": "સર્વર સાચવેલા ચુકવણી સંદર્ભની સ્થિતિ જાણી શક્યું નથી. સંદર્ભ રાખ્યો છે. નવા ચુકવણા પહેલાં મૂળ દુકાન અને પર્યાવરણમાં રિફ્રેશ કરો.",
    "The server verified your payment, but this device could not refresh or save subscription details. Local synchronization is incomplete. Refresh when connected; do not pay again for this purchase.": "સર્વરે ચુકવણી ચકાસી, પણ ઉપકરણ સબ્સ્ક્રિપ્શન વિગતો રિફ્રેશ કે સાચવી શક્યું નથી. સ્થાનિક સિંક અધૂરી છે. જોડાણ મળતાં રિફ્રેશ કરો; આ ખરીદી માટે ફરી ચૂકવશો નહીં.",
    "There are no pending, failed, or conflicted local operations.": "કોઈ બાકી, નિષ્ફળ કે વિવાદિત સ્થાનિક કામગીરી નથી.",
    "This customer can pay up to the existing outstanding balance.": "આ ગ્રાહક હાલના બાકી બેલેન્સ સુધી ચૂકવી શકે છે.",
    "This month’s collection": "આ મહિનાની વસૂલાત",
    "This month’s udhari": "આ મહિનાની ઉધારી",
