    "Your referral code": "તમારો રેફરલ કોડ",
    "Your wallet payment is verified. See My Subscription for its activation schedule.": "વૉલેટ ચુકવણી ચકાસાઈ. સક્રિય થવાનો સમય મારી સબ્સ્ક્રિપ્શનમાં જુઓ.",
