    "Upcoming subscription": "આગામી સબ્સ્ક્રિપ્શન",
    "Offline · cached entitlement": "ઓફલાઇન · સંગ્રહિત અધિકાર",
    "Confirm purchase": "ખરીદીની પુષ્ટિ કરો",
    "The device could not read or save the payment reference. Existing references were retained. Refresh before trying again.": "ઉપકરણ ચુકવણીનો સંદર્ભ વાંચી કે સાચવી શક્યું નથી. જૂના સંદર્ભો જાળવ્યા છે. ફરી પ્રયાસ કરતાં પહેલાં રિફ્રેશ કરો.",
    "Payment status could not be confirmed. Any saved payment reference is retained. Refresh to verify before paying again.": "ચુકવણીની સ્થિતિની પુષ્ટિ થઈ નથી. સાચવેલો સંદર્ભ જાળવ્યો છે. ફરી ચૂકવતાં પહેલાં રિફ્રેશ કરીને ચકાસો.",
    "The server did not authorize checkout. Refresh your subscription details.": "સર્વરે ચેકઆઉટની મંજૂરી આપી નથી. સબ્સ્ક્રિપ્શન વિગતો રિફ્રેશ કરો.",
    "The server could not establish the final payment status. Your saved reference is retained. Refresh before paying again.": "સર્વર ચુકવણીની અંતિમ સ્થિતિ નક્કી કરી શક્યું નથી. સાચવેલો સંદર્ભ જાળવ્યો છે. ફરી પ્રયાસ કરતાં પહેલાં રિફ્રેશ કરો.",
    "{{plan}} will activate after verified payment.": "{{plan}} ચકાસેલી ચુકવણી પછી સક્રિય થશે.",
    "Your new {{plan}} subscription will start after the preceding subscription commitments.": "તમારું નવું {{plan}} સબ્સ્ક્રિપ્શન અગાઉનાં સબ્સ્ક્રિપ્શન પછી શરૂ થશે.",
    "Higher-tier subscription active. {{minutes}} minutes of paid time preserved.": "ઉચ્ચ સ્તરનું સબ્સ્ક્રિપ્શન સક્રિય છે. ચૂકવેલા સમયની {{minutes}} મિનિટ સાચવેલી છે.",
    "{{plan}} will activate after verified payment. Your remaining {{days}} days of {{previous}} will be preserved and resume after higher-tier subscriptions finish.": "{{plan}} ચકાસેલી ચુકવણી પછી સક્રિય થશે. બાકીના {{days}} દિવસ {{previous}} માટે સાચવાશે અને ઉચ્ચ સ્તરનાં સબ્સ્ક્રિપ્શન પૂરાં થયા પછી ફરી શરૂ થશે.",
    "Your payment is verified. The subscription is active or scheduled as shown in My Subscription.": "તમારી ચુકવણી ચકાસાઈ છે. સક્રિય થવાનો સમય મારું સબ્સ્ક્રિપ્શનમાં જુઓ.",
    "Archived": "આર્કાઇવ કરેલા",
    "Dates for immediate activation begin at server verification.": "તાત્કાલિક સક્રિયતાની તારીખો સર્વર ચકાસણીથી શરૂ થાય છે.",
    "Your wallet contribution and Cashfree payment are verified. See My Subscription for its activation schedule.": "તમારી ચુકવણી ચકાસાઈ છે. સક્રિય થવાનો સમય મારું સબ્સ્ક્રિપ્શનમાં જુઓ.",
    "Total": "કુલ",
