    "cancelled": "રદ",
    "Start independent purchase": "નવી સ્વતંત્ર ખરીદી શરૂ કરો",
    "An earlier payment is unresolved. A new purchase can charge you again. If both payments succeed, both subscriptions will be fulfilled. The earlier reference will be retained.": "અગાઉની ચુકવણી અનિર્ણિત છે. નવી ખરીદીથી ફરી ચાર્જ થઈ શકે છે. બંને સફળ થશે તો બંને સબ્સ્ક્રિપ્શન મળશે. જૂનો સંદર્ભ સાચવવામાં આવશે.",
    "Check Payment Status": "સબ્સ્ક્રિપ્શન રિફ્રેશ / બાકી ચુકવણી તપાસો",
