    "The server verified your payment, but this device could not refresh or save subscription details. Local synchronization is incomplete. Refresh when connected; do not pay again for this purchase.": "सर्वर ने भुगतान सत्यापित किया, पर डिवाइस सदस्यता विवरण रीफ़्रेश या सहेज नहीं सका। स्थानीय सिंक अधूरा है। इंटरनेट मिलने पर रीफ़्रेश करें; इस खरीद का दोबारा भुगतान न करें।",
    "There are no pending, failed, or conflicted local operations.": "कोई लंबित, विफल या विवादित स्थानीय कार्य नहीं है।",
