    "{{plan}} will activate after verified payment. Your remaining {{days}} days of {{previous}} will be preserved and resume after higher-tier subscriptions finish.": "{{plan}} सत्यापित भुगतान के बाद सक्रिय होगा। आपके {{days}} दिन शेष {{previous}} के सुरक्षित रहेंगे और ऊँची श्रेणी की सदस्यताओं के बाद फिर चलेंगे।",
