    "Select active customers": "ಸಕ್ರಿಯ ಗ್ರಾಹಕರನ್ನು ಆಯ್ಕೆಮಾಡಿ",
    "Select active customers within your plan limit. Existing records and outstanding payment collection remain available.": "ಯೋಜನೆಯ ಮಿತಿಯಲ್ಲಿ ಸಕ್ರಿಯ ಗ್ರಾಹಕರನ್ನು ಆಯ್ಕೆಮಾಡಿ. ಹಳೆಯ ದಾಖಲೆಗಳು ಮತ್ತು ಬಾಕಿ ವಸೂಲಿ ಲಭ್ಯವಿರುತ್ತವೆ.",
