    "Subscription unavailable": "ಚಂದಾ ಲಭ್ಯವಿಲ್ಲ",
    "Subtotal": "ಉಪಮೊತ್ತ",
    "Suggest recently active customers": "ಇತ್ತೀಚೆಗೆ ಸಕ್ರಿಯ ಗ್ರಾಹಕರನ್ನು ಸೂಚಿಸಿ",
    "The Free plan is already available without checkout.": "ಉಚಿತ ಯೋಜನೆ ಪಾವತಿಯಿಲ್ಲದೆ ಲಭ್ಯವಿದೆ.",
    "The payment is not confirmed yet. Your subscription will update after Cashfree verification. Use Refresh in Subscription & Billing to check again.": "ಪಾವತಿ ಇನ್ನೂ ದೃಢಪಟ್ಟಿಲ್ಲ. Cashfree ಪರಿಶೀಲನೆಯ ಬಳಿಕ ಚಂದಾ ನವೀಕರಿಸುತ್ತದೆ. ಚಂದಾ ಮತ್ತು ಬಿಲ್ಲಿಂಗ್‌ನಲ್ಲಿ ರಿಫ್ರೆಶ್ ಮಾಡಿ.",
    "The server applied your selection. Archived customers retain all history and outstanding-payment collection.": "ಸರ್ವರ್ ಆಯ್ಕೆಯನ್ನು ಅನ್ವಯಿಸಿದೆ. ಸಂಗ್ರಹಿತ ಗ್ರಾಹಕರ ಇತಿಹಾಸ ಮತ್ತು ಬಾಕಿ ವಸೂಲಿ ಉಳಿಯುತ್ತವೆ.",
    "The server checks your available wallet balance again when creating the order. Any remainder is paid through Cashfree.": "ಆರ್ಡರ್ ಮಾಡುವಾಗ ಸರ್ವರ್ ವಾಲೆಟ್ ಬಾಕಿಯನ್ನು ಮತ್ತೆ ಪರಿಶೀಲಿಸುತ್ತದೆ. ಉಳಿದ ಮೊತ್ತ Cashfree ಮೂಲಕ ಪಾವತಿಯಾಗುತ್ತದೆ.",
    "The server confirmed this payment failed. You can try again.": "ಪಾವತಿ ವಿಫಲವಾಗಿದೆ ಎಂದು ಸರ್ವರ್ ದೃಢಪಡಿಸಿದೆ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಬಹುದು.",
    "The server could not establish the status of this saved payment reference. It has been retained. Refresh in the original shop and environment before starting another payment.": "ಉಳಿಸಿದ ಪಾವತಿ ಉಲ್ಲೇಖದ ಸ್ಥಿತಿಯನ್ನು ಸರ್ವರ್ ನಿರ್ಧರಿಸಲಾಗಲಿಲ್ಲ. ಉಲ್ಲೇಖ ಉಳಿದಿದೆ. ಹೊಸ ಪಾವತಿಯ ಮೊದಲು ಮೂಲ ಅಂಗಡಿ ಮತ್ತು ಪರಿಸರದಲ್ಲಿ ರಿಫ್ರೆಶ್ ಮಾಡಿ.",
    "The server verified your payment, but this device could not refresh or save subscription details. Local synchronization is incomplete. Refresh when connected; do not pay again for this purchase.": "ಸರ್ವರ್ ಪಾವತಿ ಪರಿಶೀಲಿಸಿದೆ; ಸಾಧನ ಚಂದಾ ವಿವರ ರಿಫ್ರೆಶ್ ಅಥವಾ ಉಳಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಸ್ಥಳೀಯ ಸಿಂಕ್ ಅಪೂರ್ಣವಾಗಿದೆ. ಸಂಪರ್ಕಿಸಿದಾಗ ರಿಫ್ರೆಶ್ ಮಾಡಿ; ಈ ಖರೀದಿಗೆ ಮತ್ತೆ ಪಾವತಿಸಬೇಡಿ.",
    "There are no pending, failed, or conflicted local operations.": "ಬಾಕಿ, ವಿಫಲ ಅಥವಾ ಸಂಘರ್ಷದ ಸ್ಥಳೀಯ ಕಾರ್ಯಗಳಿಲ್ಲ.",
    "This customer can pay up to the existing outstanding balance.": "ಈ ಗ್ರಾಹಕ ಪ್ರಸ್ತುತ ಬಾಕಿಯವರೆಗೆ ಪಾವತಿಸಬಹುದು.",
