    "Confirm purchase": "ಖರೀದಿಯನ್ನು ದೃಢೀಕರಿಸಿ",
    "The device could not read or save the payment reference. Existing references were retained. Refresh before trying again.": "ಸಾಧನಕ್ಕೆ ಪಾವತಿ ಉಲ್ಲೇಖವನ್ನು ಓದಲು ಅಥವಾ ಉಳಿಸಲು ಆಗಲಿಲ್ಲ. ಹಿಂದಿನ ಉಲ್ಲೇಖಗಳನ್ನು ಉಳಿಸಲಾಗಿದೆ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸುವ ಮೊದಲು ರಿಫ್ರೆಶ್ ಮಾಡಿ.",
    "Payment status could not be confirmed. Any saved payment reference is retained. Refresh to verify before paying again.": "ಪಾವತಿ ಸ್ಥಿತಿಯನ್ನು ದೃಢೀಕರಿಸಲಾಗಲಿಲ್ಲ. ಉಳಿಸಿದ ಉಲ್ಲೇಖವನ್ನು ಇರಿಸಲಾಗಿದೆ. ಮತ್ತೆ ಪಾವತಿಸುವ ಮೊದಲು ರಿಫ್ರೆಶ್ ಮಾಡಿ ಪರಿಶೀಲಿಸಿ.",
    "The server did not authorize checkout. Refresh your subscription details.": "ಸರ್ವರ್ ಚೆಕ್‌ಔಟ್‌ಗೆ ಅನುಮತಿ ನೀಡಲಿಲ್ಲ. ಚಂದಾದಾರಿಕೆ ವಿವರಗಳನ್ನು ರಿಫ್ರೆಶ್ ಮಾಡಿ.",
    "The server could not establish the final payment status. Your saved reference is retained. Refresh before paying again.": "ಸರ್ವರ್ ಪಾವತಿಯ ಅಂತಿಮ ಸ್ಥಿತಿಯನ್ನು ನಿರ್ಧರಿಸಲಾಗಲಿಲ್ಲ. ಉಳಿಸಿದ ಉಲ್ಲೇಖವನ್ನು ಇರಿಸಲಾಗಿದೆ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸುವ ಮೊದಲು ರಿಫ್ರೆಶ್ ಮಾಡಿ.",
    "{{plan}} will activate after verified payment.": "{{plan}} ಪರಿಶೀಲಿಸಿದ ಪಾವತಿಯ ನಂತರ ಸಕ್ರಿಯವಾಗುತ್ತದೆ.",
    "Your new {{plan}} subscription will start after the preceding subscription commitments.": "ನಿಮ್ಮ ಹೊಸ {{plan}} ಚಂದಾದಾರಿಕೆ ಹಿಂದಿನ ಚಂದಾದಾರಿಕೆಗಳ ನಂತರ ಆರಂಭವಾಗುತ್ತದೆ.",
    "Higher-tier subscription active. {{minutes}} minutes of paid time preserved.": "ಮೇಲಿನ ಹಂತದ ಚಂದಾದಾರಿಕೆ ಸಕ್ರಿಯವಾಗಿದೆ. ಪಾವತಿಸಿದ ಸಮಯದ {{minutes}} ನಿಮಿಷಗಳನ್ನು ಉಳಿಸಲಾಗಿದೆ.",
    "{{plan}} will activate after verified payment. Your remaining {{days}} days of {{previous}} will be preserved and resume after higher-tier subscriptions finish.": "{{plan}} ಪರಿಶೀಲಿಸಿದ ಪಾವತಿಯ ನಂತರ ಸಕ್ರಿಯವಾಗುತ್ತದೆ. ಉಳಿದ {{days}} ದಿನಗಳ {{previous}} ಸಮಯವನ್ನು ಉಳಿಸಿ ಮೇಲಿನ ಹಂತದ ಚಂದಾದಾರಿಕೆಗಳು ಮುಗಿದಾಗ ಮುಂದುವರಿಸಲಾಗುತ್ತದೆ.",
    "Your payment is verified. The subscription is active or scheduled as shown in My Subscription.": "ನಿಮ್ಮ ಪಾವತಿಯನ್ನು ಪರಿಶೀಲಿಸಲಾಗಿದೆ. ಆರಂಭದ ಸಮಯವನ್ನು ನನ್ನ ಚಂದಾದಾರಿಕೆಯಲ್ಲಿ ನೋಡಿ.",
    "Archived": "ಆರ್ಕೈವ್ ಮಾಡಲಾಗಿದೆ",
    "Dates for immediate activation begin at server verification.": "ತಕ್ಷಣದ ಸಕ್ರಿಯತೆಯ ದಿನಾಂಕಗಳು ಸರ್ವರ್ ಪರಿಶೀಲನೆಯಿಂದ ಆರಂಭವಾಗುತ್ತವೆ.",
    "Your wallet contribution and Cashfree payment are verified. See My Subscription for its activation schedule.": "ನಿಮ್ಮ ಪಾವತಿಯನ್ನು ಪರಿಶೀಲಿಸಲಾಗಿದೆ. ಆರಂಭದ ಸಮಯವನ್ನು ನನ್ನ ಚಂದಾದಾರಿಕೆಯಲ್ಲಿ ನೋಡಿ.",
    "Total": "ಒಟ್ಟು",
    "expired": "ಅವಧಿ ಮುಗಿದಿದೆ",
