    "An earlier payment is unresolved. A new purchase can charge you again. If both payments succeed, both subscriptions will be fulfilled. The earlier reference will be retained.": "ಹಿಂದಿನ ಪಾವತಿ ಸ್ಥಿತಿ ನಿರ್ಧಾರವಾಗಿಲ್ಲ. ಹೊಸ ಖರೀದಿಯಿಂದ ಮತ್ತೆ ಹಣ ಕಡಿತವಾಗಬಹುದು. ಎರಡೂ ಯಶಸ್ವಿಯಾದರೆ ಎರಡೂ ಚಂದಾದಾರಿಕೆಗಳು ಸಿಗುತ್ತವೆ. ಹಳೆಯ ಉಲ್ಲೇಖ ಉಳಿಸಲಾಗುತ್ತದೆ.",
