    "The server applied your selection. Archived customers retain all history and outstanding-payment collection.": "सर्व्हरान निवड लागू केल्या. संग्रहित ग्राहकांचो इतिहास आनी बाकी वसुली उरतली.",
    "The server checks your available wallet balance again when creating the order. Any remainder is paid through Cashfree.": "ऑर्डर करतना सर्व्हर वॉलेट शिल्लक परत तपासता. उरिल्ली रक्कम Cashfree वरवीं भरतात.",
    "The server confirmed this payment failed. You can try again.": "सर्व्हरान भरपाय असफळ जाल्याची खात्री केल्या. परत यत्न करूं येता.",
    "The server could not establish the status of this saved payment reference. It has been retained. Refresh in the original shop and environment before starting another payment.": "सर्व्हराक जतन केल्ल्या भरपाय संदर्भाची स्थिती कळूंक ना. संदर्भ दवरला. नव्या भरपाये पयलीं मूळ दुकान आनी वातावरणांत रिफ्रेश करात.",
    "The server verified your payment, but this device could not refresh or save subscription details. Local synchronization is incomplete. Refresh when connected; do not pay again for this purchase.": "सर्व्हरान भरपाय तपासल्या, पूण साधनाक सदस्यत्व तपशील रिफ्रेश वा जतन करूं शकले ना. थळावें समक्रमण अपुरें आसा. जोडणी मेळ्ळ्यार रिफ्रेश करात; ह्या खरेदीखातीर परत पैसे भरू नाकात.",
    "There are no pending, failed, or conflicted local operations.": "उरिल्ली, असफळ वा विवादित थळावी कामां नात.",
    "This customer can pay up to the existing outstanding balance.": "हो ग्राहक सद्याच्या बाकी मेरेन भरूं शकता.",
    "This month’s collection": "ह्या म्हयन्याची वसुली",
