    "Payment status could not be confirmed. Any saved payment reference is retained. Refresh to verify before paying again.": "फारीक स्थितीची खात्री जावंक ना. सांठयल्लो संदर्भ राखला. परत फारीक करचे पयलीं रिफ्रेश करून तपासात.",
