    "The server could not establish the final payment status. Your saved reference is retained. Refresh before paying again.": "सर्व्हराक फारीक अंतिम स्थिती थारावपाक मेळ्ळी ना. सांठयल्लो संदर्भ राखला. परत यत्न करचे पयलीं रिफ्रेश करात.",
