    "Your new {{plan}} subscription will start after the preceding subscription commitments.": "तुमची नवी {{plan}} वर्गणी आदल्या वर्गणींचे उपरांत सुरू जातली.",
    "Higher-tier subscription active. {{minutes}} minutes of paid time preserved.": "वयरल्या पांवड्याची वर्गणी सक्रिय आसा. विकत घेतिल्ल्या वेळाचीं {{minutes}} मिनिटां राखल्यांत.",
    "{{plan}} will activate after verified payment. Your remaining {{days}} days of {{previous}} will be preserved and resume after higher-tier subscriptions finish.": "{{plan}} तपासिल्ल्या फारीक उपरांत सक्रिय जातलें. उरिल्ले {{days}} दीस {{previous}} खातीर राखतले आनी वयरल्या पांवड्याच्यो वर्गण्यो सोंपल्या उपरांत परत सुरू जातले.",
    "Your payment is verified. The subscription is active or scheduled as shown in My Subscription.": "तुमची फारीक तपासल्या. सुरू जावपाचो वेळ म्हजी वर्गणींत पळयात.",
