    "3:45 PM": "ഉച്ചയ്ക്ക് ശേഷം 3:45",
    "A previous subscription payment is still awaiting Cashfree verification. Use Refresh to check it again. No new payment was started.": "മുൻ സബ്‌സ്‌ക്രിപ്‌ഷൻ പണം Cashfree പരിശോധന കാത്തിരിക്കുന്നു. പുതുക്കി വീണ്ടും നോക്കുക. പുതിയ പേയ്‌മെന്റ് തുടങ്ങിയിട്ടില്ല.",
    "Apply selection": "തിരഞ്ഞെടുപ്പ് പ്രയോഗിക്കുക",
    "Archived customers": "ആർക്കൈവ് ചെയ്ത ഉപഭോക്താക്കൾ",
    "Archived · outstanding payments only": "ആർക്കൈവ് · കുടിശ്ശിക ശേഖരണം മാത്രം",
    "Available to use toward eligible subscription purchases. Wallet balance and spending are confirmed by the server.": "യോഗ്യമായ സബ്‌സ്‌ക്രിപ്‌ഷൻ വാങ്ങാൻ ഉപയോഗിക്കാം. വാലറ്റ് ബാലൻസും ചെലവും സർവർ സ്ഥിരീകരിക്കുന്നു.",
    "Base price": "അടിസ്ഥാന വില",
    "Cashfree checkout is not enabled for this app build.": "ഈ ആപ്പ് ബിൽഡിൽ Cashfree പേയ്‌മെന്റ് പ്രവർത്തനക്ഷമമല്ല.",
    "Cashfree did not confirm a successful payment. You can try again.": "Cashfree വിജയകരമായ പേയ്‌മെന്റ് സ്ഥിരീകരിച്ചില്ല. വീണ്ടും ശ്രമിക്കാം.",
    "Cashfree paid": "Cashfree വഴി അടച്ചത്",
    "Cashfree uses native payment modules and cannot run in Expo Go. Install an Android or iOS development build first.": "Cashfree നേറ്റീവ് പേയ്‌മെന്റ് മൊഡ്യൂളുകൾ Expo Goയിൽ പ്രവർത്തിക്കില്ല. ആദ്യം Android അല്ലെങ്കിൽ iOS ഡെവലപ്‌മെന്റ് ബിൽഡ് ഇൻസ്റ്റാൾ ചെയ്യുക.",
