    "Suggest recently active customers": "അടുത്തിടെ സജീവമായ ഉപഭോക്താക്കളെ നിർദ്ദേശിക്കുക",
    "The Free plan is already available without checkout.": "സൗജന്യ പ്ലാൻ പേയ്‌മെന്റില്ലാതെ ലഭ്യമാണ്.",
    "The payment is not confirmed yet. Your subscription will update after Cashfree verification. Use Refresh in Subscription & Billing to check again.": "പേയ്‌മെന്റ് ഇതുവരെ സ്ഥിരീകരിച്ചില്ല. Cashfree പരിശോധനയ്ക്കുശേഷം സബ്‌സ്‌ക്രിപ്‌ഷൻ പുതുക്കും. സബ്‌സ്‌ക്രിപ്‌ഷനും ബില്ലിംഗും തുറന്ന് പുതുക്കുക.",
    "The server applied your selection. Archived customers retain all history and outstanding-payment collection.": "സർവർ തിരഞ്ഞെടുപ്പ് പ്രയോഗിച്ചു. ആർക്കൈവ് ഉപഭോക്താക്കളുടെ ചരിത്രവും കുടിശ്ശിക ശേഖരണവും തുടരും.",
    "The server checks your available wallet balance again when creating the order. Any remainder is paid through Cashfree.": "ഓർഡർ സൃഷ്ടിക്കുമ്പോൾ സർവർ വാലറ്റ് ബാലൻസ് വീണ്ടും പരിശോധിക്കും. ബാക്കി Cashfree വഴി അടയ്ക്കും.",
    "The server confirmed this payment failed. You can try again.": "പേയ്‌മെന്റ് പരാജയപ്പെട്ടതായി സർവർ സ്ഥിരീകരിച്ചു. വീണ്ടും ശ്രമിക്കാം.",
    "The server could not establish the status of this saved payment reference. It has been retained. Refresh in the original shop and environment before starting another payment.": "സൂക്ഷിച്ച പേയ്‌മെന്റ് റഫറൻസിന്റെ നില സർവറിന് ഉറപ്പാക്കാനായില്ല. റഫറൻസ് നിലനിർത്തി. പുതിയ പേയ്‌മെന്റിന് മുമ്പ് യഥാർത്ഥ കടയിലും പരിതസ്ഥിതിയിലും പുതുക്കുക.",
    "The server verified your payment, but this device could not refresh or save subscription details. Local synchronization is incomplete. Refresh when connected; do not pay again for this purchase.": "സർവർ പേയ്‌മെന്റ് പരിശോധിച്ചു; ഉപകരണത്തിന് സബ്‌സ്‌ക്രിപ്‌ഷൻ വിവരങ്ങൾ പുതുക്കാനോ സൂക്ഷിക്കാനോ കഴിഞ്ഞില്ല. പ്രാദേശിക സമന്വയം അപൂർണ്ണം. ബന്ധിപ്പിക്കുമ്പോൾ പുതുക്കുക; ഈ വാങ്ങലിന് വീണ്ടും പണമടയ്ക്കരുത്.",
    "There are no pending, failed, or conflicted local operations.": "ബാക്കി, പരാജയപ്പെട്ട അല്ലെങ്കിൽ വൈരുദ്ധ്യമുള്ള പ്രാദേശിക പ്രവർത്തനങ്ങളില്ല.",
    "This customer can pay up to the existing outstanding balance.": "ഈ ഉപഭോക്താവിന് നിലവിലെ കുടിശ്ശികവരെ അടയ്ക്കാം.",
    "This month’s collection": "ഈ മാസത്തെ ശേഖരണം",
    "This month’s udhari": "ഈ മാസത്തെ കടം",
    "This payment belongs to another shop. Sign in to that shop to verify it before starting another payment.": "ഈ പേയ്‌മെന്റ് മറ്റൊരു കടയുടേതാണ്. പുതിയ പേയ്‌മെന്റിന് മുമ്പ് ആ കടയിൽ പ്രവേശിച്ച് പരിശോധിക്കുക.",
    "This transaction is no longer active.": "ഈ ഇടപാട് ഇനി സജീവമല്ല.",
    "This transaction is no longer available in the active ledger. Refresh the account before editing it.": "ഈ ഇടപാട് സജീവ ഖാതയിൽ ഇല്ല. തിരുത്തും മുമ്പ് അക്കൗണ്ട് പുതുക്കുക.",
    "This transaction is no longer in Deleted Transactions.": "ഈ ഇടപാട് ഇനി നീക്കിയ ഇടപാടുകളിൽ ഇല്ല.",
    "Time · AM/PM": "സമയം · രാവിലേ/ഉച്ചയ്ക്കുശേഷം",
    "Toggle AM or PM": "രാവിലേ അല്ലെങ്കിൽ ഉച്ചയ്ക്കുശേഷം മാറ്റുക",
