    "Transaction unavailable": "ഇടപാട് ലഭ്യമല്ല",
    "Unable to share referral": "റഫറൽ പങ്കിടാനായില്ല",
    "Use date and time": "തീയതിയും സമയവും ഉപയോഗിക്കുക",
