    "The server could not establish the status of this saved payment reference. It has been retained. Refresh in the original shop and environment before starting another payment.": "सर्व्हरला जतन केलेल्या देयक संदर्भाची स्थिती ठरवता आली नाही. संदर्भ कायम आहे. नवीन देयकापूर्वी मूळ दुकान व वातावरणात रीफ्रेश करा.",
    "The server verified your payment, but this device could not refresh or save subscription details. Local synchronization is incomplete. Refresh when connected; do not pay again for this purchase.": "सर्व्हरने देयक पडताळले, पण डिव्हाइस सदस्यत्व तपशील रीफ्रेश किंवा जतन करू शकले नाही. स्थानिक समक्रमण अपूर्ण आहे. जोडणी मिळाल्यावर रीफ्रेश करा; या खरेदीसाठी पुन्हा पैसे भरू नका.",
    "There are no pending, failed, or conflicted local operations.": "प्रलंबित, अयशस्वी किंवा विवादित स्थानिक कामे नाहीत.",
