    "Configure EXPO_PUBLIC_REFERRAL_BASE_URL in the mobile build to share the public referral landing page. The code can still be shared for manual entry.": "ସାର୍ବଜନୀନ ରେଫରାଲ୍ ପୃଷ୍ଠା ଶେୟାର କରିବାକୁ ମୋବାଇଲ୍ ବିଲ୍ଡରେ EXPO_PUBLIC_REFERRAL_BASE_URL ସେଟ୍ କରନ୍ତୁ। ହାତରେ ଲେଖିବା ପାଇଁ କୋଡ୍ ଶେୟାର କରିପାରିବେ।",
