    "Connect and review active customers before restoring another operational customer.": "ଆଉ ଜଣେ ଗ୍ରାହକ ସକ୍ରିୟ କରିବା ପୂର୍ବରୁ ସଂଯୋଗ କରି ସକ୍ରିୟ ଗ୍ରାହକ ଦେଖନ୍ତୁ।",
    "Connect to review and apply the authoritative customer selection. Existing records remain available offline.": "ସର୍ଭରର ଗ୍ରାହକ ଚୟନ ଦେଖିବା ଓ ଲାଗୁ କରିବାକୁ ସଂଯୋଗ କରନ୍ତୁ। ପୁରୁଣା ରେକର୍ଡ ଅଫଲାଇନ୍ ରହିବ।",
    "Connection": "ସଂଯୋଗ",
    "Created on:": "ସୃଷ୍ଟି ତାରିଖ:",
    "Current plan limit": "ବର୍ତ୍ତମାନ ପ୍ଲାନ୍ ସୀମା",
    "Customer records changed. Review this form before saving.": "ଗ୍ରାହକ ରେକର୍ଡ ବଦଳିଛି। ସଞ୍ଚୟ ପୂର୍ବରୁ ଫର୍ମ ଯାଞ୍ଚ କରନ୍ତୁ।",
    "Customer restricted": "ଗ୍ରାହକ ସୀମିତ",
    "Customer selection saved": "ଗ୍ରାହକ ଚୟନ ସଞ୍ଚିତ",
    "Delete Transaction?": "କାରବାର ହଟାଇବେ?",
    "Deleted On:": "ହଟାଇବା ତାରିଖ:",
    "Deleted transactions are excluded from active balances. Restoring one returns it to the original financial date.": "ହଟାଯାଇଥିବା କାରବାର ସକ୍ରିୟ ବାଲାନ୍ସରେ ଗଣାଯାଏନାହିଁ। ପୁନରୁଦ୍ଧାର କଲେ ମୂଳ ଆର୍ଥିକ ତାରିଖ ରହେ।",
    "Development build required": "ଡେଭଲପମେଣ୍ଟ ବିଲ୍ଡ ଆବଶ୍ୟକ",
    "Edit the customer and add a valid number first.": "ପ୍ରଥମେ ଗ୍ରାହକ ବିବରଣୀରେ ସଠିକ୍ ନମ୍ବର ଯୋଡ଼ନ୍ତୁ।",
    "Enter a 10-digit Indian WhatsApp mobile number beginning with 6–9, or leave it empty.": "୬–୯ରୁ ଆରମ୍ଭ ହେଉଥିବା ୧୦ ଅଙ୍କର ଭାରତୀୟ WhatsApp ମୋବାଇଲ୍ ନମ୍ବର ଦିଅନ୍ତୁ ବା ଖାଲି ରଖନ୍ତୁ।",
    "Enter a valid time in h:mm AM/PM format, such as 3:45 PM.": "h:mm AM/PM ରୂପରେ ସଠିକ୍ ସମୟ ଦିଅନ୍ତୁ, ଯଥା ଅପରାହ୍ଣ ୩:୪୫।",
    "Enter time manually": "ସମୟ ହାତରେ ଦିଅନ୍ତୁ",
    "Expected expiry": "ଆଶାକୃତ ସମାପ୍ତି",
    "Expected start / resume": "ଆଶାକୃତ ଆରମ୍ଭ / ପୁନଃଆରମ୍ଭ",
    "Filter by Khata creation date": "ଖାତା ସୃଷ୍ଟି ତାରିଖରେ ଛାଣନ୍ତୁ",
    "Filter by customer creation date": "ଗ୍ରାହକ ସୃଷ୍ଟି ତାରିଖରେ ଛାଣନ୍ତୁ",
    "Filter by deletion date (YYYY-MM-DD)": "ହଟାଇବା ତାରିଖରେ ଛାଣନ୍ତୁ (YYYY-MM-DD)",
    "Internet connection required to purchase or renew your subscription. Your existing offline records remain available.": "ସଦସ୍ୟତା କିଣିବା ବା ନବୀକରଣ ପାଇଁ ଇଣ୍ଟରନେଟ୍ ଦରକାର। ପୁରୁଣା ଅଫଲାଇନ୍ ରେକର୍ଡ ଉପଲବ୍ଧ ରହିବ।",
    "Internet required": "ଇଣ୍ଟରନେଟ୍ ଆବଶ୍ୟକ",
    "Invite a new shopkeeper to Digital Khata. Once they create their shop and add the customer count set by the administrator, both shops receive wallet credit.": "ନୂଆ ଦୋକାନୀଙ୍କୁ Digital Khataକୁ ଆମନ୍ତ୍ରଣ କରନ୍ତୁ। ଦୋକାନ ଖୋଲି ପ୍ରଶାସକ ଧାର୍ଯ୍ୟ ସଂଖ୍ୟକ ଗ୍ରାହକ ଯୋଡ଼ିଲେ ଉଭୟ ଦୋକାନକୁ ୱାଲେଟ୍ କ୍ରେଡିଟ୍ ମିଳିବ।",
    "Khata Created On": "ଖାତା ସୃଷ୍ଟି ତାରିଖ",
