    "No deleted transactions": "ହଟାଯାଇଥିବା କାରବାର ନାହିଁ",
    "No referrals yet. Share your code to invite a new shopkeeper.": "ଏପର୍ଯ୍ୟନ୍ତ ରେଫରାଲ୍ ନାହିଁ। ନୂଆ ଦୋକାନୀଙ୍କୁ ଡାକିବାକୁ କୋଡ୍ ଶେୟାର କରନ୍ତୁ।",
    "Not added": "ଯୋଡ଼ାଯାଇନାହିଁ",
    "Only the selected customers can create new credit. Other customers remain available for viewing and outstanding-payment collection.": "କେବଳ ବଛାଯାଇଥିବା ଗ୍ରାହକଙ୍କୁ ନୂଆ ଉଧାର ଦେଇପାରିବେ। ଅନ୍ୟଙ୍କ ତଥ୍ୟ ଦେଖିବା ଓ ବକେୟା ଆଦାୟ କରିପାରିବେ।",
