    "Records changed while confirmation was open. Review the amount and try again.": "ନିଶ୍ଚିତ କରିବା ବେଳେ ରେକର୍ଡ ବଦଳିଗଲା। ରାଶି ଦେଖି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
