    "Refresh subscription / verify pending payment": "ସଦସ୍ୟତା ରିଫ୍ରେଶ୍ / ବାକି ପଇଠ ଯାଞ୍ଚ",
    "Refresh your subscription details before starting a payment.": "ପଇଠ ଆରମ୍ଭ ପୂର୍ବରୁ ସଦସ୍ୟତା ବିବରଣୀ ରିଫ୍ରେଶ୍ କରନ୍ତୁ।",
