    "Restore Deleted Transactions": "ହଟାଯାଇଥିବା କାରବାର ପୁନରୁଦ୍ଧାର କରନ୍ତୁ",
    "Restore Transaction": "କାରବାର ପୁନରୁଦ୍ଧାର କରନ୍ତୁ",
