    "Restored on this device. Synchronization will update the shop when available.": "ଏହି ଡିଭାଇସରେ ପୁନରୁଦ୍ଧାର ହୋଇଛି। ସଂଯୋଗ ମିଳିଲେ ସିଙ୍କ୍ ଦୋକାନ ଅପଡେଟ୍ କରିବ।",
    "Review customer": "ଗ୍ରାହକ ସମୀକ୍ଷା କରନ୍ତୁ",
    "Review subscription purchase": "ସଦସ୍ୟତା କ୍ରୟ ସମୀକ୍ଷା କରନ୍ତୁ",
    "Review transaction": "କାରବାର ସମୀକ୍ଷା କରନ୍ତୁ",
    "Review your choices before applying. Archiving preserves customers, balances and history. Selection changes require connectivity.": "ଲାଗୁ ପୂର୍ବରୁ ଚୟନ ଦେଖନ୍ତୁ। ସଂରକ୍ଷଣରେ ଗ୍ରାହକ, ବାଲାନ୍ସ ଓ ଇତିହାସ ସୁରକ୍ଷିତ। ଚୟନ ବଦଳାଇବାକୁ ସଂଯୋଗ ଦରକାର।",
