    "Search customer, transaction ID or type": "ଗ୍ରାହକ, କାରବାର ଆଇଡି ବା ପ୍ରକାର ଖୋଜନ୍ତୁ",
    "Search customers by name, mobile number, address or creation date": "ନାମ, ମୋବାଇଲ୍, ଠିକଣା ବା ସୃଷ୍ଟି ତାରିଖରେ ଗ୍ରାହକ ଖୋଜନ୍ତୁ",
    "Search name, mobile, address or date": "ନାମ, ମୋବାଇଲ୍, ଠିକଣା ବା ତାରିଖ ଖୋଜନ୍ତୁ",
    "Search recent transactions by customer name, mobile number, address or date": "ଗ୍ରାହକ ନାମ, ମୋବାଇଲ୍, ଠିକଣା ବା ତାରିଖରେ ସାମ୍ପ୍ରତିକ କାରବାର ଖୋଜନ୍ତୁ",
    "Select active / restore archived customers": "ସକ୍ରିୟ ବାଛନ୍ତୁ / ସଂରକ୍ଷିତ ଗ୍ରାହକ ଫେରାନ୍ତୁ",
    "Select active customers": "ସକ୍ରିୟ ଗ୍ରାହକ ବାଛନ୍ତୁ",
    "Select active customers within your plan limit. Existing records and outstanding payment collection remain available.": "ପ୍ଲାନ୍ ସୀମା ଭିତରେ ସକ୍ରିୟ ଗ୍ରାହକ ବାଛନ୍ତୁ। ପୁରୁଣା ରେକର୍ଡ ଓ ବକେୟା ଆଦାୟ ଉପଲବ୍ଧ ରହିବ।",
    "Selected": "ବଛାଯାଇଛି",
    "Selection needs review": "ଚୟନ ସମୀକ୍ଷା ଆବଶ୍ୟକ",
    "Share referral link": "ରେଫରାଲ୍ ଲିଙ୍କ୍ ଶେୟାର କରନ୍ତୁ",
    "Subscription Wallet": "ସଦସ୍ୟତା ୱାଲେଟ୍",
    "Subscription access changed. Refresh and review active customers before adding credit.": "ସଦସ୍ୟତା ଅନୁମତି ବଦଳିଛି। ଉଧାର ପୂର୍ବରୁ ରିଫ୍ରେଶ୍ କରି ସକ୍ରିୟ ଗ୍ରାହକ ଦେଖନ୍ତୁ।",
    "Subscription unavailable": "ସଦସ୍ୟତା ଉପଲବ୍ଧ ନାହିଁ",
    "Subtotal": "ଉପମୋଟ",
    "Suggest recently active customers": "ସାମ୍ପ୍ରତିକ ସକ୍ରିୟ ଗ୍ରାହକ ସୁପାରିଶ କରନ୍ତୁ",
    "The Free plan is already available without checkout.": "ମାଗଣା ପ୍ଲାନ୍ ପଇଠ ବିନା ଉପଲବ୍ଧ।",
    "The payment is not confirmed yet. Your subscription will update after Cashfree verification. Use Refresh in Subscription & Billing to check again.": "ପଇଠ ଏପର୍ଯ୍ୟନ୍ତ ନିଶ୍ଚିତ ନୁହେଁ। Cashfree ଯାଞ୍ଚ ପରେ ସଦସ୍ୟତା ଅପଡେଟ୍ ହେବ। ସଦସ୍ୟତା ଓ ବିଲିଂରେ ରିଫ୍ରେଶ୍ କରନ୍ତୁ।",
    "The server applied your selection. Archived customers retain all history and outstanding-payment collection.": "ସର୍ଭର ଚୟନ ଲାଗୁ କରିଛି। ସଂରକ୍ଷିତ ଗ୍ରାହକଙ୍କ ଇତିହାସ ଓ ବକେୟା ଆଦାୟ ରହିବ।",
    "The server checks your available wallet balance again when creating the order. Any remainder is paid through Cashfree.": "ଅର୍ଡର କରିବା ସମୟରେ ସର୍ଭର ୱାଲେଟ୍ ବାଲାନ୍ସ ପୁଣି ଯାଞ୍ଚ କରେ। ବାକି ରାଶି Cashfreeରେ ପଇଠ ହୁଏ।",
    "The server confirmed this payment failed. You can try again.": "ସର୍ଭର ପଇଠ ବିଫଳ ହେବା ନିଶ୍ଚିତ କରିଛି। ପୁଣି ଚେଷ୍ଟା କରିପାରିବେ।",
    "The server could not establish the status of this saved payment reference. It has been retained. Refresh in the original shop and environment before starting another payment.": "ସର୍ଭର ସଞ୍ଚିତ ପଇଠ ସନ୍ଦର୍ଭର ସ୍ଥିତି ଜାଣିପାରିନାହିଁ। ସନ୍ଦର୍ଭ ରହିଛି। ନୂଆ ପଇଠ ପୂର୍ବରୁ ମୂଳ ଦୋକାନ ଓ ପରିବେଶରେ ରିଫ୍ରେଶ୍ କରନ୍ତୁ।",
    "The server verified your payment, but this device could not refresh or save subscription details. Local synchronization is incomplete. Refresh when connected; do not pay again for this purchase.": "ସର୍ଭର ପଇଠ ଯାଞ୍ଚ କରିଛି, କିନ୍ତୁ ଡିଭାଇସ୍ ସଦସ୍ୟତା ବିବରଣୀ ରିଫ୍ରେଶ୍ ବା ସଞ୍ଚୟ କରିପାରିନାହିଁ। ସ୍ଥାନୀୟ ସିଙ୍କ୍ ଅସମ୍ପୂର୍ଣ୍ଣ। ସଂଯୋଗ ହେଲେ ରିଫ୍ରେଶ୍ କରନ୍ତୁ; ଏହି କ୍ରୟ ପାଇଁ ପୁଣି ପଇଠ କରନ୍ତୁ ନାହିଁ।",
    "There are no pending, failed, or conflicted local operations.": "ବାକି, ବିଫଳ ବା ବିବାଦୀୟ ସ୍ଥାନୀୟ କାମ ନାହିଁ।",
    "This customer can pay up to the existing outstanding balance.": "ଏହି ଗ୍ରାହକ ବର୍ତ୍ତମାନ ବକେୟା ପର୍ଯ୍ୟନ୍ତ ପଇଠ କରିପାରିବେ।",
    "This month’s collection": "ଏହି ମାସର ଆଦାୟ",
    "This month’s udhari": "ଏହି ମାସର ଉଧାର",
    "This payment belongs to another shop. Sign in to that shop to verify it before starting another payment.": "ଏହି ପଇଠ ଅନ୍ୟ ଦୋକାନର। ନୂଆ ପଇଠ ପୂର୍ବରୁ ସେହି ଦୋକାନରେ ପ୍ରବେଶ କରି ଯାଞ୍ଚ କରନ୍ତୁ।",
    "This transaction is no longer active.": "ଏହି କାରବାର ଆଉ ସକ୍ରିୟ ନାହିଁ।",
    "This transaction is no longer available in the active ledger. Refresh the account before editing it.": "ଏହି କାରବାର ସକ୍ରିୟ ଖାତାରେ ନାହିଁ। ସମ୍ପାଦନା ପୂର୍ବରୁ ଖାତା ରିଫ୍ରେଶ୍ କରନ୍ତୁ।",
    "This transaction is no longer in Deleted Transactions.": "ଏହି କାରବାର ଆଉ ହଟାଯାଇଥିବା କାରବାରରେ ନାହିଁ।",
