    "Wallet applied (estimate)": "ୱାଲେଟ୍ ବ୍ୟବହାର (ଆନୁମାନିକ)",
    "Wallet payment was accepted. Refresh subscription details when connected to update this device.": "ୱାଲେଟ୍ ପଇଠ ଗ୍ରହଣ ହୋଇଛି। ଡିଭାଇସ୍ ଅପଡେଟ୍ ପାଇଁ ସଂଯୋଗ ହେଲେ ସଦସ୍ୟତା ରିଫ୍ରେଶ୍ କରନ୍ତୁ।",
    "Wallet rewards and subscription spending will appear here.": "ୱାଲେଟ୍ ପୁରସ୍କାର ଓ ସଦସ୍ୟତା ଖର୍ଚ୍ଚ ଏଠାରେ ଦେଖାଯିବ।",
    "Wallet used": "ବ୍ୟବହୃତ ୱାଲେଟ୍",
    "Will be archived": "ସଂରକ୍ଷିତ ହେବେ",
    "Your current plan has fewer customer slots. Review your active customer selection. Viewing and outstanding collections remain available.": "ବର୍ତ୍ତମାନ ପ୍ଲାନ୍‌ରେ ଗ୍ରାହକ ସ୍ଥାନ କମ୍। ସକ୍ରିୟ ଗ୍ରାହକ ଚୟନ ଦେଖନ୍ତୁ। ତଥ୍ୟ ଦେଖିବା ଓ ବକେୟା ଆଦାୟ ଚାଲୁ ଅଛି।",
    "Your previous payment is verified, but local synchronization is incomplete. Refresh subscription details before starting another purchase.": "ପୂର୍ବ ପଇଠ ଯାଞ୍ଚ ହୋଇଛି, କିନ୍ତୁ ସ୍ଥାନୀୟ ସିଙ୍କ୍ ଅସମ୍ପୂର୍ଣ୍ଣ। ନୂଆ କ୍ରୟ ପୂର୍ବରୁ ସଦସ୍ୟତା ରିଫ୍ରେଶ୍ କରନ୍ତୁ।",
    "Your referral code": "ଆପଣଙ୍କ ରେଫରାଲ୍ କୋଡ୍",
    "Your wallet payment is verified. See My Subscription for its activation schedule.": "ୱାଲେଟ୍ ପଇଠ ଯାଞ୍ଚ ହୋଇଛି। ସକ୍ରିୟ ସମୟ ମୋ ସଦସ୍ୟତାରେ ଦେଖନ୍ତୁ।",
    "Payment": "ଦେୟ",
    "Local synchronization failed": "ସ୍ଥାନୀୟ ସିଙ୍କ୍ ବିଫଳ",
    "Network unavailable": "ନେଟୱର୍କ ଉପଲବ୍ଧ ନାହିଁ",
    "Checkout unavailable": "ଚେକଆଉଟ୍ ଉପଲବ୍ଧ ନାହିଁ",
