    "Upcoming subscription": "ଆଗାମୀ ସଦସ୍ୟତା",
    "Offline · cached entitlement": "ଅଫଲାଇନ୍ · ସଞ୍ଚିତ ଅଧିକାର",
    "Confirm purchase": "କ୍ରୟ ନିଶ୍ଚିତ କରନ୍ତୁ",
    "The device could not read or save the payment reference. Existing references were retained. Refresh before trying again.": "ଉପକରଣ ଦେୟ ସନ୍ଦର୍ଭ ପଢ଼ି କିମ୍ବା ସଞ୍ଚୟ କରିପାରିଲା ନାହିଁ। ପୁରୁଣା ସନ୍ଦର୍ଭ ରଖାଯାଇଛି। ପୁଣି ଚେଷ୍ଟା ପୂର୍ବରୁ ରିଫ୍ରେସ୍ କରନ୍ତୁ।",
    "Payment status could not be confirmed. Any saved payment reference is retained. Refresh to verify before paying again.": "ଦେୟ ସ୍ଥିତି ନିଶ୍ଚିତ ହୋଇପାରିଲା ନାହିଁ। ସଞ୍ଚିତ ସନ୍ଦର୍ଭ ରଖାଯାଇଛି। ପୁଣି ଦେୟ ପୂର୍ବରୁ ରିଫ୍ରେସ୍ କରି ଯାଞ୍ଚ କରନ୍ତୁ।",
    "The server did not authorize checkout. Refresh your subscription details.": "ସର୍ଭର ଚେକଆଉଟ୍ ଅନୁମତି ଦେଇନାହିଁ। ସଦସ୍ୟତା ବିବରଣୀ ରିଫ୍ରେସ୍ କରନ୍ତୁ।",
    "The server could not establish the final payment status. Your saved reference is retained. Refresh before paying again.": "ସର୍ଭର ଦେୟର ଅନ୍ତିମ ସ୍ଥିତି ନିର୍ଣ୍ଣୟ କରିପାରିଲା ନାହିଁ। ସଞ୍ଚିତ ସନ୍ଦର୍ଭ ରଖାଯାଇଛି। ପୁଣି ଚେଷ୍ଟା ପୂର୍ବରୁ ରିଫ୍ରେସ୍ କରନ୍ତୁ।",
    "{{plan}} will activate after verified payment.": "{{plan}} ଯାଞ୍ଚ ହୋଇଥିବା ଦେୟ ପରେ ସକ୍ରିୟ ହେବ।",
    "Your new {{plan}} subscription will start after the preceding subscription commitments.": "ଆପଣଙ୍କ ନୂଆ {{plan}} ସଦସ୍ୟତା ପୂର୍ବ ସଦସ୍ୟତାଗୁଡ଼ିକ ପରେ ଆରମ୍ଭ ହେବ।",
    "Higher-tier subscription active. {{minutes}} minutes of paid time preserved.": "ଉଚ୍ଚ ସ୍ତରର ସଦସ୍ୟତା ସକ୍ରିୟ ଅଛି। କିଣା ସମୟର {{minutes}} ମିନିଟ୍ ସୁରକ୍ଷିତ ଅଛି।",
    "{{plan}} will activate after verified payment. Your remaining {{days}} days of {{previous}} will be preserved and resume after higher-tier subscriptions finish.": "{{plan}} ଯାଞ୍ଚ ହୋଇଥିବା ଦେୟ ପରେ ସକ୍ରିୟ ହେବ। ବାକି {{days}} ଦିନ {{previous}} ପାଇଁ ସୁରକ୍ଷିତ ରହିବ ଏବଂ ଉଚ୍ଚ ସ୍ତରର ସଦସ୍ୟତା ଶେଷ ପରେ ପୁଣି ଆରମ୍ଭ ହେବ।",
    "Your payment is verified. The subscription is active or scheduled as shown in My Subscription.": "ଆପଣଙ୍କ ଦେୟ ଯାଞ୍ଚ ହୋଇଛି। ସକ୍ରିୟ ସମୟ ମୋ ସଦସ୍ୟତାରେ ଦେଖନ୍ତୁ।",
    "Archived": "ଆର୍କାଇଭ୍ ହୋଇଥିବା",
    "Dates for immediate activation begin at server verification.": "ତତ୍କାଳ ସକ୍ରିୟ ତାରିଖ ସର୍ଭର ଯାଞ୍ଚରୁ ଆରମ୍ଭ ହୁଏ।",
    "Your wallet contribution and Cashfree payment are verified. See My Subscription for its activation schedule.": "ଆପଣଙ୍କ ଦେୟ ଯାଞ୍ଚ ହୋଇଛି। ସକ୍ରିୟ ସମୟ ମୋ ସଦସ୍ୟତାରେ ଦେଖନ୍ତୁ।",
    "Total": "ମୋଟ",
    "expired": "ମିଆଦ ଶେଷ",
    "cancelled": "ବାତିଲ",
    "Start independent purchase": "ନୂଆ ସ୍ୱତନ୍ତ୍ର କ୍ରୟ ଆରମ୍ଭ କରନ୍ତୁ",
    "An earlier payment is unresolved. A new purchase can charge you again. If both payments succeed, both subscriptions will be fulfilled. The earlier reference will be retained.": "ପୂର୍ବ ଦେୟ ସ୍ଥିତି ଅନିଶ୍ଚିତ। ନୂଆ କ୍ରୟରେ ପୁଣି ଟଙ୍କା କଟିପାରେ। ଉଭୟ ସଫଳ ହେଲେ ଉଭୟ ସଦସ୍ୟତା ମିଳିବ। ପୁରୁଣା ସନ୍ଦର୍ଭ ରହିବ।",
    "Check Payment Status": "ସଦସ୍ୟତା ରିଫ୍ରେଶ୍ / ବାକି ପଇଠ ଯାଞ୍ଚ",
    "Payment Failed": "ସର୍ଭର ପଇଠ ବିଫଳ ହେବା ନିଶ୍ଚିତ କରିଛି। ପୁଣି ଚେଷ୍ଟା କରିପାରିବେ।",
