    "Deleted On:": "ਮਿਟਾਉਣ ਦੀ ਮਿਤੀ:",
    "Deleted transactions are excluded from active balances. Restoring one returns it to the original financial date.": "ਮਿਟਾਏ ਲੈਣ-ਦੇਣ ਸਰਗਰਮ ਬਕਾਏ ਵਿੱਚ ਨਹੀਂ ਗਿਣੇ ਜਾਂਦੇ। ਬਹਾਲ ਕਰਨ ਉੱਤੇ ਅਸਲ ਵਿੱਤੀ ਮਿਤੀ ਰਹਿੰਦੀ ਹੈ।",
