    "Enter a 10-digit Indian WhatsApp mobile number beginning with 6–9, or leave it empty.": "੬–੯ ਨਾਲ ਸ਼ੁਰੂ ਹੁੰਦਾ ੧੦ ਅੰਕਾਂ ਦਾ ਭਾਰਤੀ WhatsApp ਮੋਬਾਈਲ ਨੰਬਰ ਦਿਓ ਜਾਂ ਖਾਲੀ ਛੱਡੋ।",
    "Enter a valid time in h:mm AM/PM format, such as 3:45 PM.": "h:mm AM/PM ਰੂਪ ਵਿੱਚ ਸਹੀ ਸਮਾਂ ਦਿਓ, ਜਿਵੇਂ ਦੁਪਹਿਰ ੩:੪੫।",
