    "Not added": "ਜੋੜਿਆ ਨਹੀਂ",
    "Only the selected customers can create new credit. Other customers remain available for viewing and outstanding-payment collection.": "ਸਿਰਫ਼ ਚੁਣੇ ਗਾਹਕਾਂ ਨੂੰ ਨਵੀਂ ਉਧਾਰੀ ਦੇ ਸਕਦੇ ਹੋ। ਹੋਰਾਂ ਦੇ ਵੇਰਵੇ ਵੇਖ ਸਕਦੇ ਅਤੇ ਬਕਾਇਆ ਵਸੂਲ ਸਕਦੇ ਹੋ।",
