    "Review transaction": "ਲੈਣ-ਦੇਣ ਜਾਂਚੋ",
    "Review your choices before applying. Archiving preserves customers, balances and history. Selection changes require connectivity.": "ਲਾਗੂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਚੋਣ ਜਾਂਚੋ। ਪੁਰਾਲੇਖ ਵਿੱਚ ਗਾਹਕ, ਬਕਾਇਆ ਤੇ ਇਤਿਹਾਸ ਸੁਰੱਖਿਅਤ ਹਨ। ਚੋਣ ਬਦਲਣ ਲਈ ਕਨੈਕਸ਼ਨ ਚਾਹੀਦਾ ਹੈ।",
