    "Search customer, transaction ID or type": "ਗਾਹਕ, ਲੈਣ-ਦੇਣ ਆਈਡੀ ਜਾਂ ਕਿਸਮ ਲੱਭੋ",
    "Search customers by name, mobile number, address or creation date": "ਨਾਮ, ਮੋਬਾਈਲ, ਪਤਾ ਜਾਂ ਬਣਾਉਣ ਦੀ ਮਿਤੀ ਨਾਲ ਗਾਹਕ ਲੱਭੋ",
    "Search name, mobile, address or date": "ਨਾਮ, ਮੋਬਾਈਲ, ਪਤਾ ਜਾਂ ਮਿਤੀ ਲੱਭੋ",
    "Search recent transactions by customer name, mobile number, address or date": "ਗਾਹਕ ਨਾਮ, ਮੋਬਾਈਲ, ਪਤਾ ਜਾਂ ਮਿਤੀ ਨਾਲ ਹਾਲੀਆ ਲੈਣ-ਦੇਣ ਲੱਭੋ",
    "Select active / restore archived customers": "ਸਰਗਰਮ ਚੁਣੋ / ਪੁਰਾਲੇਖ ਗਾਹਕ ਬਹਾਲ ਕਰੋ",
    "Select active customers": "ਸਰਗਰਮ ਗਾਹਕ ਚੁਣੋ",
    "Select active customers within your plan limit. Existing records and outstanding payment collection remain available.": "ਪਲਾਨ ਸੀਮਾ ਅੰਦਰ ਸਰਗਰਮ ਗਾਹਕ ਚੁਣੋ। ਪੁਰਾਣੇ ਰਿਕਾਰਡ ਤੇ ਬਕਾਇਆ ਵਸੂਲੀ ਉਪਲਬਧ ਰਹਿਣਗੇ।",
    "Selected": "ਚੁਣੇ ਹੋਏ",
    "Selection needs review": "ਚੋਣ ਜਾਂਚਣੀ ਲੋੜੀਂਦੀ",
    "Share referral link": "ਰੈਫਰਲ ਲਿੰਕ ਸਾਂਝਾ ਕਰੋ",
    "Subscription Wallet": "ਮੈਂਬਰਸ਼ਿਪ ਵਾਲਿਟ",
    "Subscription access changed. Refresh and review active customers before adding credit.": "ਮੈਂਬਰਸ਼ਿਪ ਅਧਿਕਾਰ ਬਦਲੇ। ਉਧਾਰੀ ਤੋਂ ਪਹਿਲਾਂ ਰਿਫ੍ਰੈਸ਼ ਕਰਕੇ ਸਰਗਰਮ ਗਾਹਕ ਜਾਂਚੋ।",
    "Subscription unavailable": "ਮੈਂਬਰਸ਼ਿਪ ਉਪਲਬਧ ਨਹੀਂ",
    "Subtotal": "ਉਪ-ਜੋੜ",
    "Suggest recently active customers": "ਹਾਲ ਹੀ ਸਰਗਰਮ ਗਾਹਕ ਸੁਝਾਓ",
    "The Free plan is already available without checkout.": "ਮੁਫ਼ਤ ਪਲਾਨ ਬਿਨਾਂ ਅਦਾਇਗੀ ਉਪਲਬਧ ਹੈ।",
    "The payment is not confirmed yet. Your subscription will update after Cashfree verification. Use Refresh in Subscription & Billing to check again.": "ਅਦਾਇਗੀ ਹਾਲੇ ਪੁਸ਼ਟ ਨਹੀਂ। Cashfree ਤਸਦੀਕ ਤੋਂ ਬਾਅਦ ਮੈਂਬਰਸ਼ਿਪ ਅੱਪਡੇਟ ਹੋਵੇਗੀ। ਮੈਂਬਰਸ਼ਿਪ ਤੇ ਬਿਲਿੰਗ ਵਿੱਚ ਰਿਫ੍ਰੈਸ਼ ਕਰੋ।",
    "The server applied your selection. Archived customers retain all history and outstanding-payment collection.": "ਸਰਵਰ ਨੇ ਚੋਣ ਲਾਗੂ ਕੀਤੀ। ਪੁਰਾਲੇਖ ਗਾਹਕਾਂ ਦਾ ਇਤਿਹਾਸ ਤੇ ਬਕਾਇਆ ਵਸੂਲੀ ਰਹਿਣਗੇ।",
    "The server checks your available wallet balance again when creating the order. Any remainder is paid through Cashfree.": "ਆਰਡਰ ਬਣਾਉਣ ਵੇਲੇ ਸਰਵਰ ਵਾਲਿਟ ਬਕਾਇਆ ਮੁੜ ਜਾਂਚਦਾ ਹੈ। ਬਾਕੀ ਰਕਮ Cashfree ਰਾਹੀਂ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ।",
    "The server confirmed this payment failed. You can try again.": "ਸਰਵਰ ਨੇ ਅਦਾਇਗੀ ਅਸਫ਼ਲ ਹੋਣ ਦੀ ਪੁਸ਼ਟੀ ਕੀਤੀ। ਮੁੜ ਕੋਸ਼ਿਸ਼ ਕਰ ਸਕਦੇ ਹੋ।",
    "The server could not establish the status of this saved payment reference. It has been retained. Refresh in the original shop and environment before starting another payment.": "ਸਰਵਰ ਸੰਭਾਲੇ ਅਦਾਇਗੀ ਹਵਾਲੇ ਦੀ ਸਥਿਤੀ ਨਹੀਂ ਜਾਣ ਸਕਿਆ। ਹਵਾਲਾ ਰੱਖਿਆ ਹੈ। ਨਵੀਂ ਅਦਾਇਗੀ ਤੋਂ ਪਹਿਲਾਂ ਅਸਲ ਦੁਕਾਨ ਤੇ ਵਾਤਾਵਰਨ ਵਿੱਚ ਰਿਫ੍ਰੈਸ਼ ਕਰੋ।",
    "The server verified your payment, but this device could not refresh or save subscription details. Local synchronization is incomplete. Refresh when connected; do not pay again for this purchase.": "ਸਰਵਰ ਨੇ ਅਦਾਇਗੀ ਤਸਦੀਕ ਕੀਤੀ, ਪਰ ਡਿਵਾਈਸ ਮੈਂਬਰਸ਼ਿਪ ਵੇਰਵੇ ਰਿਫ੍ਰੈਸ਼ ਜਾਂ ਸੰਭਾਲ ਨਹੀਂ ਸਕਿਆ। ਸਥਾਨਕ ਸਿੰਕ ਅਧੂਰਾ ਹੈ। ਜੁੜਨ ਉੱਤੇ ਰਿਫ੍ਰੈਸ਼ ਕਰੋ; ਇਸ ਖਰੀਦ ਦੀ ਮੁੜ ਅਦਾਇਗੀ ਨਾ ਕਰੋ।",
    "There are no pending, failed, or conflicted local operations.": "ਕੋਈ ਬਾਕੀ, ਅਸਫ਼ਲ ਜਾਂ ਟਕਰਾਅ ਵਾਲਾ ਸਥਾਨਕ ਕੰਮ ਨਹੀਂ।",
    "This customer can pay up to the existing outstanding balance.": "ਇਹ ਗਾਹਕ ਮੌਜੂਦਾ ਬਕਾਏ ਤੱਕ ਹੀ ਭਰ ਸਕਦਾ ਹੈ।",
    "This month’s collection": "ਇਸ ਮਹੀਨੇ ਦੀ ਵਸੂਲੀ",
    "This month’s udhari": "ਇਸ ਮਹੀਨੇ ਦੀ ਉਧਾਰੀ",
    "This payment belongs to another shop. Sign in to that shop to verify it before starting another payment.": "ਇਹ ਅਦਾਇਗੀ ਹੋਰ ਦੁਕਾਨ ਦੀ ਹੈ। ਨਵੀਂ ਅਦਾਇਗੀ ਤੋਂ ਪਹਿਲਾਂ ਉਸ ਦੁਕਾਨ ਵਿੱਚ ਸਾਈਨ ਇਨ ਕਰਕੇ ਤਸਦੀਕ ਕਰੋ।",
