    "Wallet rewards and subscription spending will appear here.": "ਵਾਲਿਟ ਇਨਾਮ ਤੇ ਮੈਂਬਰਸ਼ਿਪ ਖਰਚ ਇੱਥੇ ਦਿਸਣਗੇ।",
