    "Will be archived": "ਪੁਰਾਲੇਖ ਵਿੱਚ ਜਾਣਗੇ",
    "Your current plan has fewer customer slots. Review your active customer selection. Viewing and outstanding collections remain available.": "ਮੌਜੂਦਾ ਪਲਾਨ ਵਿੱਚ ਗਾਹਕ ਥਾਵਾਂ ਘੱਟ ਹਨ। ਸਰਗਰਮ ਗਾਹਕ ਚੋਣ ਜਾਂਚੋ। ਵੇਖਣਾ ਤੇ ਬਕਾਇਆ ਵਸੂਲੀ ਜਾਰੀ ਹਨ।",
    "Your previous payment is verified, but local synchronization is incomplete. Refresh subscription details before starting another purchase.": "ਪਿਛਲੀ ਅਦਾਇਗੀ ਤਸਦੀਕ ਹੋਈ, ਪਰ ਸਥਾਨਕ ਸਿੰਕ ਅਧੂਰਾ ਹੈ। ਨਵੀਂ ਖਰੀਦ ਤੋਂ ਪਹਿਲਾਂ ਮੈਂਬਰਸ਼ਿਪ ਰਿਫ੍ਰੈਸ਼ ਕਰੋ।",
    "Your referral code": "ਤੁਹਾਡਾ ਰੈਫਰਲ ਕੋਡ",
    "Your wallet payment is verified. See My Subscription for its activation schedule.": "ਵਾਲਿਟ ਅਦਾਇਗੀ ਤਸਦੀਕ ਹੋਈ। ਸਰਗਰਮੀ ਦਾ ਸਮਾਂ ਮੇਰੀ ਮੈਂਬਰਸ਼ਿਪ ਵਿੱਚ ਵੇਖੋ।",
