    "Paused subscription": "ਰੋਕੀ ਹੋਈ ਮੈਂਬਰਸ਼ਿਪ",
    "Upcoming subscription": "ਆਉਣ ਵਾਲੀ ਮੈਂਬਰਸ਼ਿਪ",
    "Offline · cached entitlement": "ਔਫਲਾਈਨ · ਸੰਭਾਲਿਆ ਹੱਕ",
    "Confirm purchase": "ਖਰੀਦ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ",
    "The device could not read or save the payment reference. Existing references were retained. Refresh before trying again.": "ਡਿਵਾਈਸ ਭੁਗਤਾਨ ਦਾ ਹਵਾਲਾ ਪੜ੍ਹ ਜਾਂ ਸੰਭਾਲ ਨਹੀਂ ਸਕੀ। ਪੁਰਾਣੇ ਹਵਾਲੇ ਰੱਖੇ ਹਨ। ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਤੋਂ ਪਹਿਲਾਂ ਰਿਫ੍ਰੈਸ਼ ਕਰੋ।",
    "Payment status could not be confirmed. Any saved payment reference is retained. Refresh to verify before paying again.": "ਭੁਗਤਾਨ ਦੀ ਸਥਿਤੀ ਦੀ ਪੁਸ਼ਟੀ ਨਹੀਂ ਹੋ ਸਕੀ। ਸੰਭਾਲਿਆ ਹਵਾਲਾ ਰੱਖਿਆ ਹੈ। ਦੁਬਾਰਾ ਭੁਗਤਾਨ ਤੋਂ ਪਹਿਲਾਂ ਰਿਫ੍ਰੈਸ਼ ਕਰਕੇ ਜਾਂਚੋ।",
    "The server did not authorize checkout. Refresh your subscription details.": "ਸਰਵਰ ਨੇ ਚੈੱਕਆਉਟ ਦੀ ਇਜਾਜ਼ਤ ਨਹੀਂ ਦਿੱਤੀ। ਮੈਂਬਰਸ਼ਿਪ ਦੇ ਵੇਰਵੇ ਰਿਫ੍ਰੈਸ਼ ਕਰੋ।",
    "The server could not establish the final payment status. Your saved reference is retained. Refresh before paying again.": "ਸਰਵਰ ਭੁਗਤਾਨ ਦੀ ਅੰਤਿਮ ਸਥਿਤੀ ਨਿਰਧਾਰਤ ਨਹੀਂ ਕਰ ਸਕਿਆ। ਸੰਭਾਲਿਆ ਹਵਾਲਾ ਰੱਖਿਆ ਹੈ। ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਤੋਂ ਪਹਿਲਾਂ ਰਿਫ੍ਰੈਸ਼ ਕਰੋ।",
    "{{plan}} will activate after verified payment.": "{{plan}} ਪ੍ਰਮਾਣਿਤ ਭੁਗਤਾਨ ਤੋਂ ਬਾਅਦ ਸਰਗਰਮ ਹੋਵੇਗਾ।",
    "Your new {{plan}} subscription will start after the preceding subscription commitments.": "ਤੁਹਾਡੀ ਨਵੀਂ {{plan}} ਮੈਂਬਰਸ਼ਿਪ ਪਿਛਲੀਆਂ ਮੈਂਬਰਸ਼ਿਪਾਂ ਤੋਂ ਬਾਅਦ ਸ਼ੁਰੂ ਹੋਵੇਗੀ।",
    "Higher-tier subscription active. {{minutes}} minutes of paid time preserved.": "ਉੱਚ ਪੱਧਰ ਦੀ ਮੈਂਬਰਸ਼ਿਪ ਸਰਗਰਮ ਹੈ। ਖਰੀਦੇ ਸਮੇਂ ਦੇ {{minutes}} ਮਿੰਟ ਸੰਭਾਲੇ ਹਨ।",
    "{{plan}} will activate after verified payment. Your remaining {{days}} days of {{previous}} will be preserved and resume after higher-tier subscriptions finish.": "{{plan}} ਪ੍ਰਮਾਣਿਤ ਭੁਗਤਾਨ ਤੋਂ ਬਾਅਦ ਸਰਗਰਮ ਹੋਵੇਗਾ। ਬਾਕੀ {{days}} ਦਿਨ {{previous}} ਲਈ ਸੰਭਾਲੇ ਜਾਣਗੇ ਅਤੇ ਉੱਚ ਪੱਧਰ ਦੀਆਂ ਮੈਂਬਰਸ਼ਿਪਾਂ ਮੁੱਕਣ ਤੋਂ ਬਾਅਦ ਮੁੜ ਸ਼ੁਰੂ ਹੋਣਗੇ।",
    "Your payment is verified. The subscription is active or scheduled as shown in My Subscription.": "ਤੁਹਾਡਾ ਭੁਗਤਾਨ ਪ੍ਰਮਾਣਿਤ ਹੈ। ਸਰਗਰਮ ਹੋਣ ਦਾ ਸਮਾਂ ਮੇਰੀ ਮੈਂਬਰਸ਼ਿਪ ਵਿੱਚ ਵੇਖੋ।",
