    "An earlier payment is unresolved. A new purchase can charge you again. If both payments succeed, both subscriptions will be fulfilled. The earlier reference will be retained.": "ਪਿਛਲੇ ਭੁਗਤਾਨ ਦੀ ਸਥਿਤੀ ਅਨਿਸ਼ਚਿਤ ਹੈ। ਨਵੀਂ ਖਰੀਦ ਨਾਲ ਦੁਬਾਰਾ ਪੈਸੇ ਕੱਟ ਸਕਦੇ ਹਨ। ਦੋਵੇਂ ਸਫਲ ਹੋਏ ਤਾਂ ਦੋਵੇਂ ਮੈਂਬਰਸ਼ਿਪਾਂ ਮਿਲਣਗੀਆਂ। ਪੁਰਾਣਾ ਹਵਾਲਾ ਸੰਭਾਲਿਆ ਰਹੇਗਾ।",
