    "Available to use toward eligible subscription purchases. Wallet balance and spending are confirmed by the server.": "ᱡᱚᱜᱚᱛ ᱥᱚᱫᱚᱥᱭᱚᱛᱟ ᱠᱤᱨᱤᱧ ᱨᱮ ᱵᱮᱵᱷᱟᱨ ᱦᱚᱭ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ। ᱣᱟᱞᱮᱴ ᱴᱟᱠᱟ ᱟᱨ ᱠᱷᱚᱨᱚᱪ ᱥᱟᱨᱵᱷᱟᱨ ᱴᱷᱤᱠᱟᱹᱣᱟ।",
