    "Check automatic date and time for accurate timestamps. You can continue using Digital-Khata offline.": "ᱴᱷᱤᱠ ᱚᱠᱛᱚ ᱞᱟᱹᱜᱤᱫ ᱱᱤᱡᱮ ᱪᱟᱞᱟᱜ ᱢᱟᱹᱦᱤᱛ ᱟᱨ ᱚᱠᱛᱚ ᱧᱮᱞ ᱢᱮ। Digital-Khata ᱚᱯᱷᱞᱟᱭᱤᱱ ᱵᱮᱵᱷᱟᱨ ᱢᱮ।",
