    "Configure EXPO_PUBLIC_REFERRAL_BASE_URL in the mobile build to share the public referral landing page. The code can still be shared for manual entry.": "ᱯᱟᱵᱞᱤᱠ ᱨᱮᱯᱷᱮᱨᱟᱞ ᱯᱟᱛᱟ ᱦᱟᱹᱴᱤᱧ ᱞᱟᱹᱜᱤᱫ ᱢᱚᱵᱟᱭᱤᱞ ᱵᱤᱞᱰ ᱨᱮ EXPO_PUBLIC_REFERRAL_BASE_URL ᱥᱮᱴ ᱢᱮ। ᱛᱤ ᱛᱮ ᱟᱫᱮᱨ ᱞᱟᱹᱜᱤᱫ ᱠᱚᱰ ᱦᱟᱹᱴᱤᱧ ᱢᱮ।",
