    "Enter a valid time in h:mm AM/PM format, such as 3:45 PM.": "h:mm AM/PM ᱨᱩᱯ ᱨᱮ ᱴᱷᱤᱠ ᱚᱠᱛᱚ ᱮᱢ ᱢᱮ, ᱡᱮᱞᱮᱠᱟ ᱟᱹᱨᱤᱯ ᱓:᱔᱕।",
