    "Higher-tier subscription active. {{minutes}} minutes of paid time preserved.": "ᱪᱮᱛᱟᱱ ᱛᱟᱞᱟ ᱥᱚᱫᱚᱥᱭᱚᱛᱟ ᱮᱠᱴᱤᱵᱷ ᱢᱮᱱᱟᱜᱼᱟ᱾ ᱠᱤᱨᱤᱧ ᱚᱠᱛᱚᱨᱮᱭᱟᱜ {{minutes}} ᱢᱤᱱᱤᱴ ᱫᱚᱦᱚ ᱟᱠᱟᱱᱟ᱾",
