    "The payment is not confirmed yet. Your subscription will update after Cashfree verification. Use Refresh in Subscription & Billing to check again.": "ادائيگي اڃا پڪي ناهي. Cashfree تصديق کان پوءِ رڪنيت اپڊيٽ ٿيندي. رڪنيت ۽ بلنگ ۾ ريفريش ڪريو.",
    "The server applied your selection. Archived customers retain all history and outstanding-payment collection.": "سرور چونڊ لاڳو ڪئي. محفوظ گراهڪن جي تاريخ ۽ رهيل رقم وصولي برقرار رهندي.",
    "The server checks your available wallet balance again when creating the order. Any remainder is paid through Cashfree.": "آرڊر ٺاهڻ مهل سرور والٽ بيلنس وري جاچي ٿو. باقي رقم Cashfree وسيلي ڏني وڃي ٿي.",
    "The server confirmed this payment failed. You can try again.": "سرور ادائيگي ناڪام ٿيڻ جي پڪ ڪئي. ٻيهر ڪوشش ڪري سگهو ٿا.",
    "The server could not establish the status of this saved payment reference. It has been retained. Refresh in the original shop and environment before starting another payment.": "سرور سانڍيل ادائيگي حوالي جي حالت نه ڄاڻي سگهيو. حوالو رکيل آهي. نئين ادائيگي کان اڳ اصل دڪان ۽ ماحول ۾ ريفريش ڪريو.",
    "The server verified your payment, but this device could not refresh or save subscription details. Local synchronization is incomplete. Refresh when connected; do not pay again for this purchase.": "سرور ادائيگي تصديق ڪئي، پر اوزار رڪنيت تفصيل ريفريش يا سانڍي نه سگهيو. مقامي هم آهنگي اڻپوري آهي. ڳنڍجڻ تي ريفريش ڪريو؛ هن خريد لاءِ ٻيهر ادائيگي نه ڪريو.",
    "There are no pending, failed, or conflicted local operations.": "ڪو رهيل، ناڪام يا تڪراري مقامي ڪم ناهي.",
    "This customer can pay up to the existing outstanding balance.": "هي گراهڪ هاڻوڪي رهيل رقم تائين ادا ڪري سگهي ٿو.",
