    "Payment status could not be confirmed. Any saved payment reference is retained. Refresh to verify before paying again.": "ادائيگي جي حالت جي تصديق نه ٿي سگهي. محفوظ حوالو برقرار آهي. ٻيهر ادائيگي کان اڳ تازو ڪري جاچيو.",
    "The server did not authorize checkout. Refresh your subscription details.": "سرور چيڪ آئوٽ جي اجازت نه ڏني. رڪنيت جا تفصيل تازا ڪريو.",
    "The server could not establish the final payment status. Your saved reference is retained. Refresh before paying again.": "سرور ادائيگي جي آخري حالت طئي نه ڪري سگهيو. محفوظ حوالو برقرار آهي. ٻيهر ڪوشش کان اڳ تازو ڪريو.",
