    "{{plan}} will activate after verified payment. Your remaining {{days}} days of {{previous}} will be preserved and resume after higher-tier subscriptions finish.": "{{plan}} تصديق ٿيل ادائيگي کان پوءِ فعال ٿيندو. باقي {{days}} ڏينهن {{previous}} لاءِ محفوظ رهندا ۽ مٿئين درجي جون رڪنيتون ختم ٿيڻ کان پوءِ ٻيهر شروع ٿيندا.",
    "Your payment is verified. The subscription is active or scheduled as shown in My Subscription.": "توهان جي ادائيگي جي تصديق ٿي وئي. فعال ٿيڻ جو وقت منهنجي رڪنيت ۾ ڏسو.",
    "Archived": "آرڪائيو ڪيل",
    "Dates for immediate activation begin at server verification.": "فوري فعال ٿيڻ جون تاريخون سرور جي تصديق کان شروع ٿين ٿيون.",
    "Your wallet contribution and Cashfree payment are verified. See My Subscription for its activation schedule.": "توهان جي ادائيگي جي تصديق ٿي وئي. فعال ٿيڻ جو وقت منهنجي رڪنيت ۾ ڏسو.",
