    "Base price": "அடிப்படை விலை",
    "Cashfree checkout is not enabled for this app build.": "இந்த செயலி பதிப்பில் Cashfree கட்டணம் செயல்படுத்தப்படவில்லை.",
    "Cashfree did not confirm a successful payment. You can try again.": "Cashfree கட்டண வெற்றியை உறுதிசெய்யவில்லை. மீண்டும் முயலலாம்.",
    "Cashfree paid": "Cashfree மூலம் செலுத்தியது",
    "Cashfree uses native payment modules and cannot run in Expo Go. Install an Android or iOS development build first.": "Cashfree-இன் நேட்டிவ் கட்டண தொகுதிகள் Expo Go-வில் இயங்காது. முதலில் Android அல்லது iOS மேம்பாட்டு பதிப்பை நிறுவவும்.",
    "Check automatic date and time for accurate timestamps. You can continue using Digital-Khata offline.": "துல்லியமான பதிவுகளுக்கு தானியங்கி தேதி மற்றும் நேரத்தைச் சரிபார்க்கவும். Digital-Khata-வை இணையமின்றி பயன்படுத்தலாம்.",
    "Choose a paid plan": "கட்டணத் திட்டத்தைத் தேர்ந்தெடுக்கவும்",
