    "Configure EXPO_PUBLIC_REFERRAL_BASE_URL in the mobile build to share the public referral landing page. The code can still be shared for manual entry.": "பொது பரிந்துரைப் பக்கத்தைப் பகிர மொபைல் பதிப்பில் EXPO_PUBLIC_REFERRAL_BASE_URL அமைக்கவும். கைமுறையாக உள்ளிட குறியீட்டைப் பகிரலாம்.",
