    "Connect to review and apply the authoritative customer selection. Existing records remain available offline.": "சேவையக வாடிக்கையாளர் தேர்வைப் பார்க்கவும் பயன்படுத்தவும் இணையத்தில் இணைக. பழைய பதிவுகள் இணையமின்றிக் கிடைக்கும்.",
