    "Deleted transactions are excluded from active balances. Restoring one returns it to the original financial date.": "நீக்கிய பரிவர்த்தனைகள் தற்போதைய இருப்பில் சேராது. மீட்டால் அசல் நிதித் தேதிக்குத் திரும்பும்.",
    "Development build required": "மேம்பாட்டு பதிப்பு தேவை",
    "Edit the customer and add a valid number first.": "முதலில் வாடிக்கையாளர் விவரத்தில் சரியான எண்ணைச் சேர்க்கவும்.",
    "Enter a 10-digit Indian WhatsApp mobile number beginning with 6–9, or leave it empty.": "6–9 இல் தொடங்கும் 10 இலக்க இந்திய WhatsApp எண்ணை உள்ளிடவும் அல்லது காலியாக விடவும்.",
    "Enter a valid time in h:mm AM/PM format, such as 3:45 PM.": "h:mm AM/PM வடிவில் சரியான நேரத்தை உள்ளிடவும், எ.கா. பிற்பகல் 3:45.",
