    "Filter by customer creation date": "வாடிக்கையாளர் உருவாக்கிய தேதியால் வடிகட்டு",
    "Filter by deletion date (YYYY-MM-DD)": "நீக்கிய தேதியால் வடிகட்டு (YYYY-MM-DD)",
