    "Internet required": "இணையம் தேவை",
    "Invite a new shopkeeper to Digital Khata. Once they create their shop and add the customer count set by the administrator, both shops receive wallet credit.": "புதிய கடைக்காரரை Digital Khata-க்கு அழைக்கவும். கடை உருவாக்கி நிர்வாகி நிர்ணயித்த எண்ணிக்கையில் வாடிக்கையாளர்களைச் சேர்த்ததும் இரு கடைகளுக்கும் பணப்பை வரவு கிடைக்கும்.",
