    "Base price": "మూల ధర",
    "Cashfree checkout is not enabled for this app build.": "ఈ యాప్ బిల్డ్‌లో Cashfree చెల్లింపు ప్రారంభించలేదు.",
    "Cashfree did not confirm a successful payment. You can try again.": "Cashfree విజయవంతమైన చెల్లింపును నిర్ధారించలేదు. మళ్లీ ప్రయత్నించవచ్చు.",
    "Cashfree paid": "Cashfree ద్వారా చెల్లించినది",
    "Cashfree uses native payment modules and cannot run in Expo Go. Install an Android or iOS development build first.": "Cashfree స్థానిక చెల్లింపు మాడ్యూళ్లు Expo Goలో పనిచేయవు. ముందుగా Android లేదా iOS డెవలప్‌మెంట్ బిల్డ్ ఇన్‌స్టాల్ చేయండి.",
    "Check automatic date and time for accurate timestamps. You can continue using Digital-Khata offline.": "సరైన సమయాల కోసం ఆటోమేటిక్ తేదీ, సమయం తనిఖీ చేయండి. Digital-Khata ఆఫ్‌లైన్‌లో వాడవచ్చు.",
