    "Clear Khata customer date filter": "ఖాతా కస్టమర్ తేదీ ఫిల్టర్ తొలగించండి",
    "Clear creation date filter": "సృష్టించిన తేదీ ఫిల్టర్ తొలగించండి",
    "Clear customer creation date filter": "కస్టమర్ సృష్టించిన తేదీ ఫిల్టర్ తొలగించండి",
