    "Configure EXPO_PUBLIC_REFERRAL_BASE_URL in the mobile build to share the public referral landing page. The code can still be shared for manual entry.": "పబ్లిక్ రెఫరల్ పేజీ పంచుకోవడానికి మొబైల్ బిల్డ్‌లో EXPO_PUBLIC_REFERRAL_BASE_URL సెట్ చేయండి. చేతితో నమోదు చేయడానికి కోడ్ పంచుకోవచ్చు.",
    "Confirm customer selection": "కస్టమర్ ఎంపిక నిర్ధారించండి",
    "Connect and review active customers before restoring another operational customer.": "మరో కస్టమర్‌ను సక్రియం చేసే ముందు కనెక్ట్ అయి సక్రియ కస్టమర్లను సమీక్షించండి.",
    "Connect to review and apply the authoritative customer selection. Existing records remain available offline.": "సర్వర్ కస్టమర్ ఎంపికను చూసి వర్తింపజేయడానికి కనెక్ట్ అవ్వండి. పాత రికార్డులు ఆఫ్‌లైన్‌లో ఉంటాయి.",
