    "Customer records changed. Review this form before saving.": "కస్టమర్ రికార్డులు మారాయి. సేవ్ చేసే ముందు ఫారమ్ సమీక్షించండి.",
    "Customer restricted": "కస్టమర్‌పై పరిమితి",
    "Customer selection saved": "కస్టమర్ ఎంపిక సేవ్ అయింది",
