    "Deleted On:": "తొలగించిన తేదీ:",
    "Deleted transactions are excluded from active balances. Restoring one returns it to the original financial date.": "తొలగించిన లావాదేవీలు ప్రస్తుత నిల్వలో చేరవు. పునరుద్ధరిస్తే అసలు ఆర్థిక తేదీకి తిరిగి వస్తాయి.",
    "Development build required": "డెవలప్‌మెంట్ బిల్డ్ అవసరం",
    "Edit the customer and add a valid number first.": "ముందుగా కస్టమర్ వివరాల్లో సరైన నంబర్ చేర్చండి.",
    "Enter a 10-digit Indian WhatsApp mobile number beginning with 6–9, or leave it empty.": "6–9తో మొదలయ్యే 10 అంకెల భారతీయ WhatsApp మొబైల్ నంబర్ ఇవ్వండి లేదా ఖాళీగా వదలండి.",
    "Enter a valid time in h:mm AM/PM format, such as 3:45 PM.": "h:mm AM/PM రూపంలో సరైన సమయం ఇవ్వండి, ఉదా. మధ్యాహ్నం 3:45.",
