    "Filter by Khata creation date": "ఖాతా సృష్టించిన తేదీతో వడపోయండి",
    "Filter by customer creation date": "కస్టమర్ సృష్టించిన తేదీతో వడపోయండి",
    "Filter by deletion date (YYYY-MM-DD)": "తొలగించిన తేదీతో వడపోయండి (YYYY-MM-DD)",
    "Internet connection required to purchase or renew your subscription. Your existing offline records remain available.": "సభ్యత్వం కొనడానికి లేదా పునరుద్ధరించడానికి ఇంటర్నెట్ కావాలి. పాత ఆఫ్‌లైన్ రికార్డులు అందుబాటులో ఉంటాయి.",
    "Internet required": "ఇంటర్నెట్ అవసరం",
    "Invite a new shopkeeper to Digital Khata. Once they create their shop and add the customer count set by the administrator, both shops receive wallet credit.": "కొత్త దుకాణదారుని Digital Khataకు ఆహ్వానించండి. దుకాణం సృష్టించి నిర్వాహకుడు నిర్ణయించిన సంఖ్యలో కస్టమర్లను చేర్చాక రెండు దుకాణాలకు వాలెట్ క్రెడిట్ లభిస్తుంది.",
