    "The Free plan is already available without checkout.": "ఉచిత ప్లాన్ చెల్లింపు లేకుండానే అందుబాటులో ఉంది.",
    "The payment is not confirmed yet. Your subscription will update after Cashfree verification. Use Refresh in Subscription & Billing to check again.": "చెల్లింపు ఇంకా నిర్ధారణ కాలేదు. Cashfree ధృవీకరణ తర్వాత సభ్యత్వం అప్‌డేట్ అవుతుంది. సభ్యత్వం, బిల్లింగ్‌లో రిఫ్రెష్ చేసి చూడండి.",
    "The server applied your selection. Archived customers retain all history and outstanding-payment collection.": "సర్వర్ ఎంపికను వర్తింపజేసింది. ఆర్కైవ్ కస్టమర్ల చరిత్ర, బాకీ వసూలు కొనసాగుతాయి.",
    "The server checks your available wallet balance again when creating the order. Any remainder is paid through Cashfree.": "ఆర్డర్ సృష్టించేటప్పుడు సర్వర్ వాలెట్ నిల్వను మళ్లీ చూస్తుంది. మిగిలిన మొత్తం Cashfreeతో చెల్లిస్తారు.",
    "The server confirmed this payment failed. You can try again.": "చెల్లింపు విఫలమైందని సర్వర్ నిర్ధారించింది. మళ్లీ ప్రయత్నించవచ్చు.",
    "The server could not establish the status of this saved payment reference. It has been retained. Refresh in the original shop and environment before starting another payment.": "సేవ్ చేసిన చెల్లింపు సూచన స్థితిని సర్వర్ నిర్ధారించలేకపోయింది. సూచన భద్రంగా ఉంది. కొత్త చెల్లింపుకు ముందు అసలు దుకాణం, వాతావరణంలో రిఫ్రెష్ చేయండి.",
    "The server verified your payment, but this device could not refresh or save subscription details. Local synchronization is incomplete. Refresh when connected; do not pay again for this purchase.": "సర్వర్ చెల్లింపును ధృవీకరించింది, కానీ పరికరం సభ్యత్వ వివరాలు రిఫ్రెష్ లేదా సేవ్ చేయలేకపోయింది. స్థానిక సమకాలీకరణ అసంపూర్ణం. కనెక్ట్ అయినప్పుడు రిఫ్రెష్ చేయండి; ఈ కొనుగోలుకు మళ్లీ చెల్లించవద్దు.",
    "There are no pending, failed, or conflicted local operations.": "పెండింగ్, విఫలమైన లేదా వైరుధ్యమున్న స్థానిక పనులు లేవు.",
    "This customer can pay up to the existing outstanding balance.": "ఈ కస్టమర్ ప్రస్తుత బాకీ వరకు చెల్లించవచ్చు.",
