    "Confirm purchase": "కొనుగోలును నిర్ధారించండి",
    "The device could not read or save the payment reference. Existing references were retained. Refresh before trying again.": "పరికరం చెల్లింపు సూచనను చదవలేకపోయింది లేదా సేవ్ చేయలేకపోయింది. పాత సూచనలు ఉంచబడ్డాయి. మళ్లీ ప్రయత్నించే ముందు రిఫ్రెష్ చేయండి.",
    "Payment status could not be confirmed. Any saved payment reference is retained. Refresh to verify before paying again.": "చెల్లింపు స్థితిని నిర్ధారించలేకపోయాం. సేవ్ చేసిన సూచన ఉంచబడింది. మళ్లీ చెల్లించే ముందు రిఫ్రెష్ చేసి ధృవీకరించండి.",
    "The server did not authorize checkout. Refresh your subscription details.": "సర్వర్ చెక్‌అవుట్‌ను అనుమతించలేదు. సభ్యత్వ వివరాలను రిఫ్రెష్ చేయండి.",
    "The server could not establish the final payment status. Your saved reference is retained. Refresh before paying again.": "సర్వర్ చెల్లింపు తుది స్థితిని నిర్ధారించలేకపోయింది. సేవ్ చేసిన సూచన ఉంచబడింది. మళ్లీ ప్రయత్నించే ముందు రిఫ్రెష్ చేయండి.",
    "{{plan}} will activate after verified payment.": "{{plan}} ధృవీకరించిన చెల్లింపు తర్వాత సక్రియమవుతుంది.",
    "Your new {{plan}} subscription will start after the preceding subscription commitments.": "మీ కొత్త {{plan}} సభ్యత్వం ముందు ఉన్న సభ్యత్వాల తర్వాత ప్రారంభమవుతుంది.",
    "Higher-tier subscription active. {{minutes}} minutes of paid time preserved.": "ఉన్నత స్థాయి సభ్యత్వం సక్రియంగా ఉంది. చెల్లించిన సమయంలో {{minutes}} నిమిషాలు భద్రపరచబడ్డాయి.",
    "{{plan}} will activate after verified payment. Your remaining {{days}} days of {{previous}} will be preserved and resume after higher-tier subscriptions finish.": "{{plan}} ధృవీకరించిన చెల్లింపు తర్వాత సక్రియమవుతుంది. మిగిలిన {{days}} రోజుల {{previous}} సమయం భద్రపరచబడి ఉన్నత స్థాయి సభ్యత్వాలు ముగిశాక తిరిగి ప్రారంభమవుతుంది.",
    "Your payment is verified. The subscription is active or scheduled as shown in My Subscription.": "మీ చెల్లింపు ధృవీకరించబడింది. ప్రారంభ సమయాన్ని నా సభ్యత్వంలో చూడండి.",
    "Archived": "ఆర్కైవ్ చేసినవి",
